import React, { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './styles/linear.css'
import './react-overrides.css'

const API = import.meta.env.VITE_API_URL || ''
const STATUS_LABELS = { backlog: 'Backlog', todo: 'Todo', in_progress: 'In Progress', done: 'Done', canceled: 'Canceled' }

async function api(path, options = {}) {
  const response = await fetch(`${API}${path}`, { credentials: 'include', ...options, headers: options.body instanceof URLSearchParams ? options.headers : { 'Content-Type': 'application/json', ...(options.headers || {}) } })
  if (!response.ok) { const body = await response.json().catch(() => ({})); const error = new Error(body.detail || `Request failed (${response.status})`); error.status = response.status; throw error }
  return response.status === 204 ? null : response.json()
}

function Icon({ name, size = 14 }) {
  const common = { width: size, height: size, viewBox: '0 0 16 16', fill: 'none', stroke: 'currentColor', strokeWidth: 1.4, strokeLinecap: 'round', strokeLinejoin: 'round', 'aria-hidden': true }
  const paths = {
    inbox: <><path d="M2 9.5 3.6 3.3a1 1 0 0 1 1-.8h6.8a1 1 0 0 1 1 .8L14 9.5v3a1 1 0 0 1-1 1H3a1 1 0 0 1-1-1z"/><path d="M2 9.5h3l.8 1.4h4.4L11 9.5h3"/></>,
    myIssues: <><circle cx="8" cy="8" r="5.6" strokeDasharray="2.6 2.2"/><circle cx="8" cy="8" r="1.9" fill="currentColor" stroke="none"/></>,
    reviews: <><circle cx="4.4" cy="4" r="1.6"/><circle cx="4.4" cy="12.2" r="1.6"/><path d="M4.4 5.6v5"/><circle cx="11.6" cy="12.2" r="1.6"/><path d="M11.6 10.6V6.4a2 2 0 0 0-2-2H7.2M8.6 3.1 7.1 4.4l1.5 1.3"/></>,
    agent: <path d="M3.4 2.8 13 8l-9.6 5.2z"/>,
    members: <><circle cx="6" cy="5.5" r="2.2"/><path d="M1.9 13c0-2.3 1.8-3.7 4.1-3.7s4.1 1.4 4.1 3.7M11 3.7a2.2 2.2 0 0 1 0 4.2M12.2 9.6c1.3.4 2.2 1.5 2.2 3.1"/></>,
    teams: <><rect x="2.4" y="2.4" width="11.2" height="11.2" rx="2.4"/><circle cx="8" cy="6.4" r="1.7"/><path d="M5 11.6c0-1.6 1.3-2.5 3-2.5s3 .9 3 2.5"/></>,
    home: <><path d="M2.6 6.8 8 2.6l5.4 4.2v6a.9.9 0 0 1-.9.9h-9a.9.9 0 0 1-.9-.9z"/><path d="M6.4 13.7V9.4h3.2v4.3"/></>,
    issues: <><rect x="2.6" y="2.6" width="10.8" height="10.8" rx="2.4"/><path d="M5.4 8h5.2M5.4 5.4h5.2M5.4 10.6h3"/></>,
    cycles: <><circle cx="8" cy="8" r="5.6"/><path d="M6.7 5.6 10.4 8l-3.7 2.4z"/></>,
    projects: <><path d="M8 2.2 13.6 5.3v5.4L8 13.8 2.4 10.7V5.3z"/><path d="M2.4 5.3 8 8.4l5.6-3.1M8 8.4v5.4"/></>,
    settings: <><circle cx="8" cy="8" r="2.1"/><path d="M8 1.6v1.6M8 12.8v1.6M14.4 8h-1.6M3.2 8H1.6M12.5 3.5l-1.1 1.1M4.6 11.4l-1.1 1.1M12.5 12.5l-1.1-1.1M4.6 4.6 3.5 3.5"/></>,
    plus: <path d="M8 3.5v9M3.5 8h9"/>,
    search: <><circle cx="7.2" cy="7.2" r="4.2"/><path d="M10.4 10.4 13.5 13.5"/></>,
    compose: <><path d="M12.8 2.6a1.4 1.4 0 0 1 2 2L7 12.4l-2.7.7.7-2.7z"/><path d="M2.5 13.6h4"/></>,
    chevron: <path d="M4 6.5 8 10.5 12 6.5"/>
  }
  return <svg className="icon" {...common}>{paths[name] || paths.chevron}</svg>
}

function TeamBadge({ team, size = 16 }) {
  if (!team) return null
  return <span className="avatar" style={{ width: size, height: size, fontSize: 9, background: team.color || '#5e6ad2' }}>{team.key.slice(0, 2)}</span>
}

function MainHeader({ page, team, issues, selectedIssue, editingIssue, selectedProject, onBack, onEdit, onNewIssue, onNewProject, pageTitle }) {
  const arrow = <Icon name="chevron" size={11} />
  if (selectedIssue && !editingIssue) return <><nav className="breadcrumb"><button className="breadcrumb-button" onClick={onBack}>{team?.name}</button><span className="breadcrumb-arrow">{arrow}</span><span className="current">{selectedIssue.identifier}</span></nav><span className="spacer" /><button className="btn btn-secondary" onClick={onEdit}>Edit</button></>
  if (editingIssue) return <><nav className="breadcrumb"><button className="breadcrumb-button" onClick={onBack}>{team?.name} Issues</button><span className="breadcrumb-arrow">{arrow}</span><span className="current">{editingIssue.identifier}</span><span className="breadcrumb-arrow">{arrow}</span><span>Edit</span></nav><span className="spacer" /></>
  if (page === 'issues' && team) return <><span className="page-title"><TeamBadge team={team} size={15} /><span>{team.name}</span><span className="muted">{issues.length}</span></span><span className="spacer" />{<button className="btn btn-secondary" onClick={onNewIssue}>＋ New issue</button>}</>
  if (page === 'my-issues') return <><span className="page-title"><Icon name="myIssues" size={15} /><span>My issues</span><span className="muted">{issues.length}</span></span><span className="spacer" /></>
  if (page === 'projects' && selectedProject) return <><nav className="breadcrumb"><button className="breadcrumb-button" onClick={onBack}>Projects</button><span className="breadcrumb-arrow">{arrow}</span><span className="current">{selectedProject.name}</span></nav><span className="spacer" /><button className="btn btn-secondary" onClick={onEdit}>Edit</button></>
  if (page === 'projects') return <><span className="page-title"><Icon name="projects" size={15} /><span>Projects</span></span><span className="spacer" />{!selectedProject && <button className="btn btn-secondary" onClick={onNewProject}>＋ New project</button>}</>
  if (page === 'cycles' || page === 'cycles-current' || page === 'cycles-upcoming') return <><span className="page-title"><Icon name="cycles" size={15} /><span>Cycles</span>{page !== 'cycles' && <span className="muted">/ {page === 'cycles-current' ? 'Current' : 'Upcoming'}</span>}</span><span className="spacer" /></>
  return <><span className="page-title">{pageTitle}</span><span className="spacer" /></>
}

function StatusIcon({ value, size = 14 }) {
  if (value === 'done') return <svg className="status-icon status-done" width={size} height={size} viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="6.2" fill="currentColor" /><path d="M4.4 7.1 6.2 8.9 9.7 5.4" fill="none" stroke="var(--bg-panel)" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" /></svg>
  if (value === 'canceled') return <svg className="status-icon status-canceled" width={size} height={size} viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="6.2" fill="currentColor" /><path d="M5 5l4 4M9 5l-4 4" fill="none" stroke="var(--bg-panel)" strokeWidth="1.6" strokeLinecap="round" /></svg>
  if (value === 'in_progress') return <svg className="status-icon status-in_progress" width={size} height={size} viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true"><circle cx="7" cy="7" r="5.5" /><path d="M7 3.1a3.9 3.9 0 0 1 0 7.8z" fill="currentColor" stroke="none" /></svg>
  return <svg className={`status-icon status-${value || 'todo'}`} width={size} height={size} viewBox="0 0 14 14" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true"><circle cx="7" cy="7" r="5.5" strokeDasharray={value === 'backlog' ? '2.2 2' : undefined} /></svg>
}

function PriorityIcon({ level = 3 }) {
  const filled = 5 - level
  return <svg className="priority-icon" width="14" height="14" viewBox="0 0 14 14" aria-hidden="true" title={`Priority ${level}`}>{[0, 1, 2, 3].map(bar => <rect key={bar} x={1 + bar * 3.2} y={10 - bar * 2.2} width="2.2" height={2.5 + bar * 2.2} rx="0.6" fill="currentColor" opacity={bar < filled ? 1 : 0.22} />)}</svg>
}

function Login({ onLogin, onRegister }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(() => new URLSearchParams(window.location.search).get('auth_error') || '')
  async function submit(event) {
    event.preventDefault(); setError('')
    const response = await fetch(`${API}/auth/token`, { method: 'POST', credentials: 'include', body: new URLSearchParams({ username, password }) })
    const valid = response.ok && await response.json().catch(() => false)
    if (!valid) { setError('Incorrect Username or Password'); return }
    onLogin()
  }
  return <div className="auth-screen"><div className="auth-card"><div className="brand"><span className="avatar lg" style={{ background: '#5e6ad2' }}>TD</span> TodoApp</div><h1>Log in</h1>{error && <div className="banner error">{error}</div>}<form onSubmit={submit}><div className="field"><label htmlFor="username">Username</label><input className="input" id="username" value={username} onChange={event => setUsername(event.target.value)} autoComplete="username" required autoFocus /></div><div className="field"><label htmlFor="password">Password</label><input className="input" id="password" type="password" value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password" required /></div><button className="btn btn-primary btn-lg btn-block" type="submit">Continue</button></form><div className="auth-divider">or</div><a className="btn btn-secondary btn-lg btn-block" href={`${API}/auth/google`}>Continue with Google</a><div className="auth-footer">Don't have an account? <button className="link-button" onClick={onRegister}>Sign up</button></div></div></div>
}

function Register({ onLogin, onBack }) {
  const [form, setForm] = useState({ username: '', email: '', first_name: '', last_name: '', password: '' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  function update(field, value) { setForm({ ...form, [field]: value }) }
  async function submit(event) { event.preventDefault(); setBusy(true); setError(''); try { const response = await api('/auth/create/user', { method: 'POST', body: JSON.stringify(form) }); if (response !== undefined) onLogin(); else onLogin() } catch (err) { setError(err.message) } finally { setBusy(false) } }
  return <div className="auth-screen"><div className="auth-card"><div className="brand"><span className="avatar lg" style={{ background: '#5e6ad2' }}>TD</span> TodoApp</div><h1>Create account</h1>{error && <div className="banner error">{error}</div>}<form onSubmit={submit}><div className="field"><label>Username</label><input className="input" value={form.username} onChange={event => update('username', event.target.value)} required autoFocus /></div><div className="field"><label>Email</label><input className="input" type="email" value={form.email} onChange={event => update('email', event.target.value)} /></div><div className="row auth-name-fields"><div className="field"><label>First name</label><input className="input" value={form.first_name} onChange={event => update('first_name', event.target.value)} required /></div><div className="field"><label>Last name</label><input className="input" value={form.last_name} onChange={event => update('last_name', event.target.value)} required /></div></div><div className="field"><label>Password</label><input className="input" type="password" value={form.password} onChange={event => update('password', event.target.value)} required /></div><button className="btn btn-primary btn-lg btn-block" disabled={busy}>{busy ? 'Creating…' : 'Create account'}</button></form><div className="auth-footer">Already have an account? <button className="link-button" onClick={onBack}>Log in</button></div></div></div>
}

function CreateWorkspace({ onCreated }) {
  const [name, setName] = useState(''); const [teamKey, setTeamKey] = useState(''); const [error, setError] = useState('')
  async function submit(event) { event.preventDefault(); try { await api('/api/workspaces', { method: 'POST', body: JSON.stringify({ name, team_key: teamKey || null }) }); onCreated() } catch (err) { setError(err.message) } }
  return <div className="auth-screen"><form className="auth-card" onSubmit={submit}><div className="brand">Todo<span>App</span></div><h1>Create workspace</h1><p className="hint">Create a workspace to start organizing your work.</p>{error && <div className="banner error">{error}</div>}<div className="field"><label>Workspace name</label><input className="input" value={name} onChange={event => setName(event.target.value)} placeholder="Acme" required autoFocus /></div><div className="field"><label>Team key</label><input className="input" value={teamKey} onChange={event => setTeamKey(event.target.value)} placeholder="TODO" /></div><button className="btn btn-primary btn-lg btn-block">Create workspace</button></form></div>
}

function InvitePage({ token }) {
  const [invite, setInvite] = useState(null); const [error, setError] = useState(''); const [accepted, setAccepted] = useState(false)
  useEffect(() => { api(`/api/invites/${token}`).then(setInvite).catch(err => setError(err.message)) }, [token])
  async function accept() { try { await api(`/api/invites/${token}/accept`, { method: 'POST' }); setAccepted(true) } catch (err) { setError(err.message) } }
  if (accepted) return <div className="auth-screen"><div className="auth-card"><h1>Invite accepted</h1><p className="hint">You joined the workspace. Reload the app to continue.</p><a className="btn btn-primary btn-block" href="/">Open TodoApp</a></div></div>
  return <div className="auth-screen"><div className="auth-card"><div className="brand">Todo<span>App</span></div><h1>Workspace invite</h1>{error && <div className="banner error">{error}</div>}{invite && <><p className="hint">You were invited to join <b>{invite.workspace.name}</b> as {invite.role}.</p><button className="btn btn-primary btn-block" disabled={invite.already_member} onClick={accept}>{invite.already_member ? 'Already a member' : 'Accept invite'}</button></>}</div></div>
}

function Sidebar({ session, team, page, onTeam, onNavigate, onNewIssue }) {
  return <nav className="sidebar" aria-label="Navigation"><div className="sidebar-top"><button className="account-switch" type="button"><span className="avatar">{session.user.name.slice(0, 2).toUpperCase()}</span><span className="name">{session.user.username}</span><span className="chevron"><Icon name="chevron" size={11} /></span></button><span className="btn-icon pending" title="Search — not built"><Icon name="search" /></span><button className="btn-icon" onClick={onNewIssue} title="New issue"><Icon name="compose" /></button></div><div className="nav-group"><span className="nav-item pending"><Icon name="inbox" /><span className="label">Inbox</span><span className="badge-soon">soon</span></span><button className={`nav-item ${page === 'my-issues' ? 'active' : ''}`} onClick={() => onNavigate('my-issues')}><Icon name="myIssues" /><span className="label">My issues</span></button><span className="nav-item pending"><Icon name="reviews" /><span className="label">Reviews</span><span className="badge-soon">soon</span></span><span className="nav-item pending"><Icon name="agent" /><span className="label">Agent</span><span className="badge-soon">soon</span></span></div><div className="sidebar-section">Workspace</div><button className={`nav-item ${page === 'members-admin' ? 'active' : ''}`} onClick={() => onNavigate('members-admin')}><Icon name="members" /><span className="label">Members</span></button><button className={`nav-item ${page === 'teams-admin' ? 'active' : ''}`} onClick={() => onNavigate('teams-admin')}><Icon name="teams" /><span className="label">Teams</span></button><div className="sidebar-section">Your teams</div>{session.teams.map(item => <div className="team-group" key={item.id}><button className={`nav-item team-head ${team?.id === item.id && page === 'home' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('home') }}><span className="avatar" style={{ background: item.color || '#5e6ad2' }}>{item.key.slice(0, 2)}</span><span className="label">{item.name}</span><span className="count">{item.key}</span></button><button className={`nav-item nested ${team?.id === item.id && page === 'issues' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('issues') }}><Icon name="issues" /><span className="label">Issues</span></button><button className={`nav-item nested ${team?.id === item.id && page === 'cycles' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('cycles') }}><Icon name="cycles" /><span className="label">Cycles</span></button><button className={`nav-item nested ${team?.id === item.id && page === 'projects' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('projects') }}><Icon name="projects" /><span className="label">Projects</span></button></div>)}<span style={{ flex: 1 }} /><button className={`nav-item ${page === 'workspace-admin' ? 'active' : ''}`} onClick={() => onNavigate('workspace-admin')}><Icon name="home" /><span className="label">Workspace</span></button><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => onNavigate('settings')}><Icon name="settings" /><span className="label">Settings</span></button></nav>
}

// JSX translation of templates/partials/sidebar.html. The class names and
// nesting intentionally mirror the original template so linear.css keeps
// rendering the same shell; only Jinja conditions/loops became React props.
function LegacyOriginalSidebar({ session, team, page, onTeam, onNavigate, onNewIssue, onLogout }) {
  const [accountOpen, setAccountOpen] = useState(false); const [workspaceOpen, setWorkspaceOpen] = useState(false)
  const current = session.workspace
  async function logout() { try { await fetch(`${API}/auth/logout`, { credentials: 'include' }) } finally { onLogout() } }
  return <nav className="sidebar" aria-label="Navigation"><div className="sidebar-top"><div className="menu-anchor" style={{ flex: 1, minWidth: 0 }}><button className="account-switch" type="button" onClick={() => setAccountOpen(!accountOpen)}><span className="avatar">{session.user.name.slice(0, 2).toUpperCase()}</span><span className="name">{session.user.username}</span><span className="chevron"><Icon name="chevron" size={11} /></span></button><div className="menu" hidden={!accountOpen} role="menu" style={{ minWidth: 220 }}><div className="menu-label">{session.user.email || session.user.username}</div><button className="menu-item" onClick={() => { setAccountOpen(false); onNavigate('settings') }}><Icon name="settings" /><span className="label">Settings</span><kbd>G</kbd><kbd>S</kbd></button><div className="menu-separator" /><button className="menu-item danger" onClick={logout}><span className="label">Log out</span><kbd>Alt</kbd><kbd>⇧</kbd><kbd>Q</kbd></button></div></div><span className="btn-icon pending" title="Search — not built"><Icon name="search" /></span>{team && <button className="btn-icon" onClick={onNewIssue} title="New issue"><Icon name="compose" /></button>}</div><div className="nav-group"><span className="nav-item pending"><Icon name="inbox" /><span className="label">Inbox</span><span className="badge-soon">soon</span></span><button className={`nav-item ${page === 'my-issues' ? 'active' : ''}`} onClick={() => onNavigate('my-issues')}><Icon name="myIssues" /><span className="label">My issues</span></button><span className="nav-item pending"><Icon name="reviews" /><span className="label">Reviews</span><span className="badge-soon">soon</span></span><span className="nav-item pending"><Icon name="agent" /><span className="label">Agent</span><span className="badge-soon">soon</span></span></div><div className="menu-anchor"><button className="sidebar-section as-button" type="button" onClick={() => setWorkspaceOpen(!workspaceOpen)}><span>Workspace</span><Icon name="chevron" size={10} /></button><div className="menu" hidden={!workspaceOpen} role="menu" style={{ minWidth: 240 }}><div className="menu-label">Workspaces</div>{(session.workspaces || [current]).filter(Boolean).map(option => <button className="menu-item" key={option.id}><span className="avatar">{option.name.slice(0, 2).toUpperCase()}</span><span className="label">{option.name}</span>{current && option.id === current.id && <span className="muted">✓</span>}</button>)}<div className="menu-separator" /><button className="menu-item" onClick={() => onNavigate('workspace-admin')}><Icon name="settings" /><span className="label">Workspace settings</span></button><button className="menu-item" onClick={() => onNavigate('workspace-create')}><Icon name="plus" /><span className="label">Create workspace</span></button></div></div><button className={`nav-item ${page === 'members-admin' ? 'active' : ''}`} onClick={() => onNavigate('members-admin')}><Icon name="members" /><span className="label">Members</span></button><button className={`nav-item ${page === 'teams-admin' ? 'active' : ''}`} onClick={() => onNavigate('teams-admin')}><Icon name="teams" /><span className="label">Teams</span></button><div className="sidebar-section">Your teams</div>{session.teams.map(item => { const here = team?.id === item.id; return <div className="team-group" key={item.id}><div className="nav-item team-head"><span className="avatar" style={{ background: item.color || '#5e6ad2' }}>{item.key.slice(0, 2)}</span><span className="label">{item.name}</span><span className="count">{item.key}</span></div><button className={`nav-item nested ${here && page === 'home' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('home') }}><Icon name="home" /><span className="label">Home</span></button><button className={`nav-item nested ${here && page === 'issues' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('issues') }}><Icon name="issues" /><span className="label">Issues</span></button><button className={`nav-item nested ${here && page === 'cycles' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('cycles') }}><Icon name="cycles" /><span className="label">Cycles</span></button><button className="nav-item nested twice" onClick={() => { onTeam(item); onNavigate('cycles') }}><span className="label">Current</span></button><button className="nav-item nested twice" onClick={() => { onTeam(item); onNavigate('cycles') }}><span className="label">Upcoming</span></button><button className={`nav-item nested ${here && page === 'projects' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('projects') }}><Icon name="projects" /><span className="label">Projects</span></button></div> })}<span style={{ flex: 1 }} /><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => onNavigate('settings')} title="Settings — G then S"><Icon name="settings" /><span className="label">Settings</span></button></nav>
}

function OriginalSidebar({ session, team, page, onTeam, onNavigate, onNewIssue, onLogout }) {
  const [accountOpen, setAccountOpen] = useState(false); const [workspaceOpen, setWorkspaceOpen] = useState(false)
  const current = session.workspace
  async function switchWorkspace(slug) { await api(`/api/workspaces/switch/${slug}`, { method: 'POST' }); window.location.reload() }
  useEffect(() => {
    function handleCycleShortcut(event) {
      const item = event.target.closest?.('.nav-item.nested.twice')
      const label = item?.querySelector('.label')?.textContent?.trim()
      if (!item || (label !== 'Current' && label !== 'Upcoming')) return
      event.preventDefault(); event.stopPropagation()
      if (team) onTeam(team)
      onNavigate(label === 'Current' ? 'cycles-current' : 'cycles-upcoming')
    }
    document.addEventListener('click', handleCycleShortcut, true)
    return () => document.removeEventListener('click', handleCycleShortcut, true)
  }, [team, onTeam, onNavigate])
  return <nav className="sidebar" aria-label="Navigation"><div className="sidebar-top"><div className="menu-anchor" style={{ flex: 1, minWidth: 0 }}><button className="account-switch" type="button" onClick={() => setAccountOpen(!accountOpen)}><span className="avatar">{session.user.name.slice(0, 2).toUpperCase()}</span><span className="name">{session.user.username}</span><span className="chevron"><Icon name="chevron" size={11} /></span></button><div className="menu" hidden={!accountOpen} role="menu" style={{ minWidth: 220 }}><div className="menu-label">{session.user.email || session.user.username}</div><button className="menu-item" onClick={() => { setAccountOpen(false); onNavigate('settings') }}><Icon name="settings" /><span className="label">Settings</span><kbd>G</kbd><kbd>S</kbd></button><div className="menu-separator" /><button className="menu-item danger" onClick={onLogout}><span className="label">Log out</span><kbd>Alt</kbd><kbd>⇧</kbd><kbd>Q</kbd></button></div></div><span className="btn-icon pending" title="Search — not built"><Icon name="search" /></span>{team && <button className="btn-icon" onClick={onNewIssue} title="New issue"><Icon name="compose" /></button>}</div><div className="nav-group"><span className="nav-item pending"><Icon name="inbox" /><span className="label">Inbox</span><span className="badge-soon">soon</span></span><button className={`nav-item ${page === 'my-issues' ? 'active' : ''}`} onClick={() => onNavigate('my-issues')}><Icon name="myIssues" /><span className="label">My issues</span></button><span className="nav-item pending"><Icon name="reviews" /><span className="label">Reviews</span><span className="badge-soon">soon</span></span><span className="nav-item pending"><Icon name="agent" /><span className="label">Agent</span><span className="badge-soon">soon</span></span></div><div className="menu-anchor"><button className="sidebar-section as-button" type="button" onClick={() => setWorkspaceOpen(!workspaceOpen)}><span>Workspace</span><Icon name="chevron" size={10} /></button><div className="menu" hidden={!workspaceOpen} role="menu" style={{ minWidth: 240 }}><div className="menu-label">Workspaces</div>{(session.workspaces || [current]).filter(Boolean).map(option => <button className="menu-item" type="button" key={option.id} onClick={() => switchWorkspace(option.slug)}><span className="avatar">{option.name.slice(0, 2).toUpperCase()}</span><span className="label">{option.name}</span>{current && option.id === current.id && <span className="muted">✓</span>}</button>)}<div className="menu-separator" /><button className="menu-item" onClick={() => onNavigate('workspace-admin')}><Icon name="settings" /><span className="label">Workspace settings</span></button><button className="menu-item" onClick={() => onNavigate('workspace-create')}><Icon name="plus" /><span className="label">Create workspace</span></button></div></div><button className={`nav-item ${page === 'members-admin' ? 'active' : ''}`} onClick={() => onNavigate('members-admin')}><Icon name="members" /><span className="label">Members</span></button><button className={`nav-item ${page === 'teams-admin' ? 'active' : ''}`} onClick={() => onNavigate('teams-admin')}><Icon name="teams" /><span className="label">Teams</span></button><div className="sidebar-section">Your teams</div>{session.teams.length ? session.teams.map(item => { const here = team?.id === item.id; return <div className="team-group" key={item.id}><div className="nav-item team-head"><TeamBadge team={item} /><span className="label">{item.name}</span><span className="count">{item.key}</span></div><button className={`nav-item nested ${here && page === 'home' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('home') }}><Icon name="home" /><span className="label">Home</span></button><button className={`nav-item nested ${here && page === 'issues' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('issues') }}><Icon name="issues" /><span className="label">Issues</span></button><button className={`nav-item nested ${here && page === 'cycles' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('cycles') }}><Icon name="cycles" /><span className="label">Cycles</span></button><button className={`nav-item nested twice ${here && page === 'cycles-current' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('cycles') }}><span className="label">Current</span></button><button className={`nav-item nested twice ${here && page === 'cycles-upcoming' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('cycles') }}><span className="label">Upcoming</span></button><button className={`nav-item nested ${here && page === 'projects' ? 'active' : ''}`} onClick={() => { onTeam(item); onNavigate('projects') }}><Icon name="projects" /><span className="label">Projects</span></button></div> }) : <span className="nav-item pending"><span className="label">No teams yet</span></span>}<span style={{ flex: 1 }} /><button className={`nav-item ${page === 'settings' ? 'active' : ''}`} onClick={() => onNavigate('settings')} title="Settings — G then S"><Icon name="settings" /><span className="label">Settings</span></button></nav>
}

function IssueStatusMenu({ issue, onStatus, triggerClass = 'status-trigger', showLabel = false }) {
  const [open, setOpen] = useState(false)
  return <div className="menu-anchor"><button className={triggerClass} type="button" title={STATUS_LABELS[issue.status]} onClick={() => setOpen(!open)}><StatusIcon value={issue.status} />{showLabel && <span>{STATUS_LABELS[issue.status]}</span>}</button><div className="menu" hidden={!open} role="menu" style={{ minWidth: 180 }}><div className="menu-label">Status</div>{Object.entries(STATUS_LABELS).map(([value, label]) => <button className="menu-item" type="button" role="menuitem" key={value} onClick={() => { setOpen(false); onStatus(issue, value) }}><StatusIcon value={value} /><span className="label">{label}</span>{value === issue.status && <span className="muted">✓</span>}</button>)}</div></div>
}

function IssueRow({ issue, onStatus, onOpen }) {
  return <li className={`issue-row is-${issue.status}`}><IssueStatusMenu issue={issue} onStatus={onStatus} /><span className="identifier">{issue.identifier}</span><button className="title issue-title-button" onClick={() => onOpen(issue)}>{issue.title}</button><PriorityIcon level={issue.priority} /><span className="avatar">{issue.assignee_id ? 'ME' : ''}</span></li>
}

function IssueList({ team, issues, onStatus, onNewIssue, onOpen }) {
  const groups = useMemo(() => Object.keys(STATUS_LABELS).map(status => [status, issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length), [issues])
  return <>{groups.length ? groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev"><Icon name="chevron" size={11} /></span><StatusIcon value={status} /><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button><span style={{ flex: 1 }} /><button className="btn-icon" onClick={onNewIssue} title="New issue"><Icon name="plus" size={13} /></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={onStatus} onOpen={onOpen} />)}</ul></section>) : <div className="empty-state"><span className="title">No issues in {team.name}</span><span>Everything the team is working on shows up here, grouped by status.</span><button className="btn btn-primary" onClick={onNewIssue}><Icon name="plus" size={13} /> New issue</button></div>}</>
}

function NewIssue({ team, onClose, onCreated }) {
  async function submit(event) { event.preventDefault(); const form = new FormData(event.currentTarget); const issue = await api(`/api/teams/${team.key}/issues`, { method: 'POST', body: JSON.stringify({ title: form.get('title'), description: form.get('description'), priority: Number(form.get('priority')), issue_status: form.get('issue_status') }) }); onCreated(issue) }
  return <div className="content-narrow"><form onSubmit={submit}><div className="field"><label htmlFor="title">Title</label><input className="input" id="title" name="title" required autoFocus placeholder="Issue title" /></div><div className="field"><label htmlFor="description">Description</label><textarea className="textarea" id="description" name="description" placeholder="Add more detail…" /></div><div className="row" style={{ gap: 12, alignItems: 'flex-end' }}><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="issue_status">Status</label><select className="select" id="issue_status" name="issue_status" defaultValue="todo">{Object.entries(STATUS_LABELS).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></div><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="priority">Priority</label><select className="select" id="priority" name="priority" defaultValue="3">{[1, 2, 3, 4, 5].map(level => <option value={level} key={level}>P{level}</option>)}</select></div></div><div className="form-actions"><button className="btn btn-primary" type="submit">Create issue</button><button className="btn btn-ghost" type="button" onClick={onClose}>Cancel</button></div></form></div>
}

function LegacyIssueDetail({ issue, onBack, onStatus, onDeleted, onEdit }) {
  const [title, setTitle] = useState(issue.title || ''); const [description, setDescription] = useState(issue.description || ''); const [priority, setPriority] = useState(issue.priority || 3)
  const [saving, setSaving] = useState(false)
  async function save() {
    setSaving(true)
    const updated = await api(`/api/issues/${issue.identifier}`, { method: 'PATCH', body: JSON.stringify({ title, description, priority: Number(priority) }) })
    setSaving(false); issue.description = updated.description
  }
  async function remove() {
    if (!window.confirm(`Delete ${issue.identifier}?`)) return
    await api(`/api/issues/${issue.identifier}`, { method: 'DELETE' }); onDeleted()
  }
  return <div className="issue-detail"><div><button className="btn btn-ghost" onClick={onBack}>← Back to issues</button><div className="detail-header"><div><p className="eyebrow">{issue.identifier}</p><h1>{issue.title}</h1></div><button className="btn btn-secondary" onClick={onEdit}>Edit</button></div><div className="issue-description">{issue.description || <span className="muted">No description</span>}</div></div><aside className="issue-props"><div className="prop-row"><span className="prop-label">Status</span><select className="select prop-value" value={issue.status} onChange={event => onStatus(issue, event.target.value)}>{Object.entries(STATUS_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="prop-row"><span className="prop-label">Priority</span><select className="select prop-value" value={priority} onChange={event => setPriority(event.target.value)}>{[1, 2, 3, 4, 5].map(level => <option key={level} value={level}>P{level}</option>)}</select></div><div className="prop-row"><span className="prop-label">Project</span><span className="prop-value">{issue.project_id ? `Project #${issue.project_id}` : 'No project'}</span></div><div className="prop-row"><span className="prop-label">Cycle</span><span className="prop-value">{issue.cycle_id ? `Cycle #${issue.cycle_id}` : 'No cycle'}</span></div><div className="prop-row"><span className="prop-label">Assignee</span><span className="prop-value">{issue.assignee_id ? 'Me' : 'Unassigned'}</span></div><div className="prop-row"><span className="prop-label">Created</span><span className="prop-value hint">{issue.created_at ? new Date(issue.created_at).toLocaleDateString() : '—'}</span></div><div className="prop-row"><span className="prop-label">Updated</span><span className="prop-value hint">{issue.updated_at ? new Date(issue.updated_at).toLocaleDateString() : '—'}</span></div><div className="menu-separator" style={{ margin: '12px 0' }} /><button className="btn btn-danger" onClick={remove}>Delete issue</button></aside></div>
}

// The content area follows templates/issues/detail.html: the page header owns
// the breadcrumb and Edit action, while the body only contains the title and
// the original property list.
function LegacyIssueDetail2({ issue, onStatus, onDeleted }) {
  async function remove() {
    if (!window.confirm(`Delete ${issue.identifier}? This cannot be undone.`)) return
    await api(`/api/issues/${issue.identifier}`, { method: 'DELETE' })
    onDeleted()
  }
  return <div className="issue-detail"><div><h1>{issue.title}</h1><div className="issue-description">{issue.description || <span className="muted">No description</span>}</div></div><aside className="issue-props"><div className="prop-row"><span className="prop-label">Status</span><select className="select prop-value" value={issue.status} onChange={event => onStatus(issue, event.target.value)}>{Object.entries(STATUS_LABELS).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></div><div className="prop-row"><span className="prop-label">Priority</span><select className="select prop-value" value={issue.priority || 3} onChange={event => api(`/api/issues/${issue.identifier}`, { method: 'PATCH', body: JSON.stringify({ priority: Number(event.target.value) }) })}>{[1, 2, 3, 4, 5].map(level => <option key={level} value={level}>P{level}</option>)}</select></div><div className="prop-row"><span className="prop-label">Project</span><span className="prop-value">{issue.project_id ? `Project #${issue.project_id}` : 'No project'}</span></div><div className="prop-row"><span className="prop-label">Cycle</span><span className="prop-value">{issue.cycle_id ? `Cycle #${issue.cycle_id}` : 'No cycle'}</span></div><div className="prop-row"><span className="prop-label">Assignee</span><span className="prop-value">{issue.assignee_id ? 'Me' : 'Unassigned'}</span></div><div className="prop-row"><span className="prop-label">Created</span><span className="prop-value hint">{issue.created_at ? new Date(issue.created_at).toLocaleDateString(undefined, { month: 'short', day: '2-digit', year: 'numeric' }) : '—'}</span></div><div className="prop-row"><span className="prop-label">Updated</span><span className="prop-value hint">{issue.updated_at ? new Date(issue.updated_at).toLocaleDateString(undefined, { month: 'short', day: '2-digit', year: 'numeric' }) : '—'}</span></div><div className="menu-separator" style={{ margin: '12px 0' }} /><button className="btn btn-danger" onClick={remove}>Delete issue</button></aside></div>
}

function PropertyMenu({ label, value, options, onChange, icon = null, emptyLabel = 'None' }) {
  const [open, setOpen] = useState(false)
  return <div className="menu-anchor"><button className="prop-value" type="button" onClick={() => setOpen(!open)}>{icon}{value ? <span>{value}</span> : <span className="muted">{emptyLabel}</span>}</button><div className="menu" hidden={!open} role="menu" style={{ minWidth: 220 }}><div className="menu-label">{label}</div><button className="menu-item" type="button" onClick={() => { setOpen(false); onChange(null) }}><span className="label muted">{emptyLabel}</span>{!value && <span className="muted">✓</span>}</button>{options.map(option => <button className="menu-item" type="button" key={option.id} onClick={() => { setOpen(false); onChange(option.id) }}><span className="label">{option.name}</span>{value === option.name && <span className="muted">✓</span>}</button>)}</div></div>
}

function PriorityMenu({ issue, onChange }) {
  const [open, setOpen] = useState(false)
  return <div className="menu-anchor"><button className="prop-value" type="button" onClick={() => setOpen(!open)}><PriorityIcon level={issue.priority} /><span>P{issue.priority}</span></button><div className="menu" hidden={!open} role="menu" style={{ minWidth: 160 }}><div className="menu-label">Priority</div>{[1, 2, 3, 4, 5].map(level => <button className="menu-item" type="button" key={level} onClick={() => { setOpen(false); onChange(level) }}><PriorityIcon level={level} /><span className="label">P{level}</span>{issue.priority === level && <span className="muted">✓</span>}</button>)}</div></div>
}

function IssueDetail({ issue, onStatus, onDeleted }) {
  const [current, setCurrent] = useState(issue); const [projects, setProjects] = useState([]); const [cycles, setCycles] = useState([])
  useEffect(() => { if (!issue.team_key) return; Promise.all([api(`/api/teams/${issue.team_key}/projects`), api(`/api/teams/${issue.team_key}/cycles`)]).then(([projectData, cycleData]) => { setProjects(projectData.projects || []); setCycles((cycleData.cycles || []).filter(item => item.state === 'current' || item.state === 'upcoming')) }) }, [issue.team_key])
  async function update(patch) { const updated = await api(`/api/issues/${current.identifier}`, { method: 'PATCH', body: JSON.stringify(patch) }); setCurrent(updated); if (patch.issue_status) onStatus(current, patch.issue_status) }
  async function remove() { if (!window.confirm(`Delete ${current.identifier}? This cannot be undone.`)) return; await api(`/api/issues/${current.identifier}`, { method: 'DELETE' }); onDeleted() }
  const project = projects.find(item => item.id === current.project_id); const cycle = cycles.find(item => item.id === current.cycle_id)
  return <div className="issue-detail"><div><h1>{current.title}</h1><div className="issue-description">{current.description || <span className="muted">No description</span>}</div></div><aside className="issue-props"><div className="prop-row"><span className="prop-label">Status</span><IssueStatusMenu issue={current} onStatus={(item, status) => update({ issue_status: status })} triggerClass="prop-value" showLabel /></div><div className="prop-row"><span className="prop-label">Priority</span><PriorityMenu issue={current} onChange={priority => update({ priority })} /></div><div className="prop-row"><span className="prop-label">Project</span><PropertyMenu label="Project" value={project?.name} options={projects} onChange={project_id => update({ project_id })} emptyLabel="No project" icon={<Icon name="projects" size={13} />} /></div><div className="prop-row"><span className="prop-label">Cycle</span><PropertyMenu label="Cycle" value={cycle?.name} options={cycles} onChange={cycle_id => update({ cycle_id })} emptyLabel="No cycle" icon={<Icon name="cycles" size={13} />} /></div><div className="prop-row"><span className="prop-label">Assignee</span><span className="prop-value">{current.assignee_id ? 'Me' : 'Unassigned'}</span></div><div className="prop-row"><span className="prop-label">Created by</span><span className="prop-value">Unknown</span></div><div className="prop-row"><span className="prop-label">Created</span><span className="prop-value hint">{current.created_at ? new Date(current.created_at).toLocaleDateString(undefined, { month: 'short', day: '2-digit', year: 'numeric' }) : '—'}</span></div><div className="prop-row"><span className="prop-label">Updated</span><span className="prop-value hint">{current.updated_at ? new Date(current.updated_at).toLocaleDateString(undefined, { month: 'short', day: '2-digit', year: 'numeric' }) : '—'}</span></div><div className="menu-separator" style={{ margin: '12px 0' }} /><button className="btn btn-danger" onClick={remove}>Delete issue</button></aside></div>
}

function EditIssue({ issue, onBack, onSaved }) {
  const [form, setForm] = useState({ title: issue.title, description: issue.description || '', priority: issue.priority || 3 })
  async function submit(event) { event.preventDefault(); const updated = await api(`/api/issues/${issue.identifier}`, { method: 'PATCH', body: JSON.stringify({ ...form, priority: Number(form.priority) }) }); onSaved(updated) }
  return <div className="content-narrow"><form onSubmit={submit}><div className="field"><label htmlFor="edit-title">Title</label><input className="input" id="edit-title" value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} required autoFocus /></div><div className="field"><label htmlFor="edit-description">Description</label><textarea className="textarea" id="edit-description" value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} /></div><div className="field" style={{ maxWidth: 160 }}><label htmlFor="edit-priority">Priority</label><select className="select" id="edit-priority" value={form.priority} onChange={event => setForm({ ...form, priority: event.target.value })}>{[1, 2, 3, 4, 5].map(level => <option value={level} key={level}>P{level}</option>)}</select></div><p className="hint">Status is changed from the issue itself, so a change lands in one click rather than behind a form.</p><div className="form-actions"><button className="btn btn-primary">Save</button><button className="btn btn-ghost" type="button" onClick={onBack}>Cancel</button></div></form></div>
}

function Projects({ team, onOpen }) {
  const [projects, setProjects] = useState([])
  useEffect(() => { api(`/api/teams/${team.key}/projects`).then(data => setProjects(data.projects)) }, [team])
  return projects.length ? <ul>{projects.map(project => {
    const percent = project.total_issues ? Math.round(project.done_issues * 100 / project.total_issues) : 0
    return <li className="project-row" key={project.id}>
      <span className={`project-status ${project.status}`} aria-hidden="true" />
      <button className="title link-button" onClick={() => onOpen(project)}>{project.name}</button>
      <span className="progress-mini" role="img" aria-label={`${project.done_issues} of ${project.total_issues} issues done`}><span style={{ width: `${percent}%` }} /></span>
      <span className="muted progress-count">{project.total_issues ? `${project.done_issues}/${project.total_issues}` : 'no issues'}</span>
      <span className={`muted target-date ${project.target_date && project.status !== 'completed' && project.target_date < new Date().toISOString().slice(0, 10) ? 'overdue' : ''}`}>{project.target_date ? new Date(`${project.target_date}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: '2-digit' }) : '—'}</span>
    </li>
  })}</ul> : <div className="empty-state"><span className="title">No projects in {team.name}</span><span>A project is a feature: one deliverable, made of several issues.</span><button className="btn btn-primary" onClick={() => onOpen({ new: true })} style={{ marginTop: 8 }}>＋ New project</button></div>
}

function LegacyCyclesOld({ team }) {
  const [cycles, setCycles] = useState([]); const [detail, setDetail] = useState(null)
  useEffect(() => { api(`/api/teams/${team.key}/cycles`).then(data => setCycles(data.cycles)) }, [team])
  async function open(state) { setDetail(await api(`/api/teams/${team.key}/cycles/${state}`)) }
  if (detail) { const groups = Object.keys(STATUS_LABELS).map(status => [status, detail.issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length); return <div className="cycle-detail"><button className="btn btn-ghost" onClick={() => setDetail(null)}>← Back to cycles</button><header className="cycle-detail-header"><div><p className="eyebrow">{detail.state.toUpperCase()}</p><h1>{detail.cycle?.name || `No ${detail.state} cycle`}</h1></div>{detail.cycle && <><span className={`cycle-state ${detail.state}`}>{detail.state}</span><span className="muted">{detail.cycle.starts_on} – {detail.cycle.ends_on}</span></>}</header>{!detail.cycle ? <div className="cycle-open"><p className="hint">Nothing scheduled into this cycle yet.</p></div> : detail.issues.length === 0 ? <div className="cycle-open"><p className="hint">Nothing scheduled into {detail.cycle.name} yet.</p></div> : groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev">⌄</span><span className={`status-dot status-${status}`}>●</span><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={() => {}} onOpen={() => {}} />)}</ul></section>)}</div> }
  return <ul>{cycles.map(cycle => { const percent = cycle.total_issues ? Math.round(cycle.done_issues * 100 / cycle.total_issues) : 0; return <li key={cycle.id}><div className={`cycle-row is-${cycle.state}`}><span className="icon"><Icon name="cycles" size={14} /></span>{cycle.state === 'current' || cycle.state === 'upcoming' ? <button className="title link-button" onClick={() => open(cycle.state)}>{cycle.name}</button> : <span className="title">{cycle.name}</span>}<span className="muted cycle-dates">{new Date(`${cycle.starts_on}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: '2-digit' })} – {new Date(`${cycle.ends_on}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: '2-digit' })}</span><span className={`cycle-state ${cycle.state}`}>{cycle.state === 'current' ? 'Current' : cycle.state === 'upcoming' ? 'Upcoming' : 'Past'}</span><span className="progress-mini" role="img" aria-label={`${cycle.done_issues} of ${cycle.total_issues} issues done`}><span style={{ width: `${percent}%` }} /></span><span className="muted progress-count">{cycle.total_issues ? `${cycle.done_issues}/${cycle.total_issues}` : '0 scope'}</span></div></li> })}</ul>
}

function CycleBurnupChart({ chart, cycleName }) {
  if (!chart) return null
  const lastDate = chart.dates?.[chart.dates.length - 1]?.text || ''
  return <figure className="cycle-open"><figcaption className="row between"><div><h2>Burn-up</h2><p className="hint">Day {chart.days_shown} of {chart.days_total}. Scope counts issues from the day they were created — nothing records when one was moved into a cycle, so an issue added late reads as having been here from the start.</p></div><div className="legend">{chart.series.map(series => <span className="legend-item" key={series.role}><span className={`key key-${series.role}`} />{series.name} <b>{series.end_value}</b></span>)}</div></figcaption><svg className="trend" viewBox={`0 0 ${chart.box.width} ${chart.box.height}`} role="img" preserveAspectRatio="xMidYMid meet" aria-label={`Burn-up for ${cycleName}`}>
    {chart.elapsed && <><rect className="remaining" x={chart.elapsed.x} y={chart.elapsed.top} width={chart.box.right - chart.elapsed.x} height={chart.elapsed.bottom - chart.elapsed.top} /><line className="today-rule" x1={chart.elapsed.x} y1={chart.elapsed.top} x2={chart.elapsed.x} y2={chart.elapsed.bottom} vectorEffect="non-scaling-stroke" /></>}
    {chart.gridlines.map(line => <g key={line.value}><line className="grid" x1={chart.box.left} y1={line.y} x2={chart.box.right} y2={line.y} vectorEffect="non-scaling-stroke" /><text className="tick" x={chart.box.left - 10} y={line.y + 4} textAnchor="end">{line.value}</text></g>)}
    {chart.series.map(series => <polyline className={`trend-line line-${series.role}`} key={series.role} points={series.points} vectorEffect="non-scaling-stroke" />)}
    {chart.series.map(series => <circle className={`trend-dot dot-${series.role}`} key={`${series.role}-dot`} cx={series.end[0]} cy={series.end[1]} r="4" />)}
    {chart.dates.map(day => <text className="tick" key={`${day.x}-${day.text}`} x={day.x} y={chart.box.height - 6} textAnchor="middle">{day.text}</text>)}
  </svg><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Series</th><th>At {lastDate}</th></tr></thead><tbody>{chart.series.map(series => <tr key={series.role}><td>{series.name}</td><td>{series.end_value}</td></tr>)}</tbody></table></details></figure>
}

function LegacyCycles({ team }) {
  const [cycles, setCycles] = useState([]); const [chart, setChart] = useState(null); const [detail, setDetail] = useState(null)
  useEffect(() => { api(`/api/teams/${team.key}/cycles`).then(data => { setCycles(data.cycles); setChart(data.chart) }) }, [team])
  async function open(state) { setDetail(await api(`/api/teams/${team.key}/cycles/${state}`)) }
  if (detail) { const groups = Object.keys(STATUS_LABELS).map(status => [status, detail.issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length); return <div><button className="btn btn-ghost" onClick={() => setDetail(null)}>← Back to cycles</button><header className="cycle-detail-header"><div><p className="eyebrow">{detail.state.toUpperCase()}</p><h1>{detail.cycle?.name || `No ${detail.state} cycle`}</h1></div>{detail.cycle && <><span className={`cycle-state ${detail.state}`}>{detail.state}</span><span className="muted">{detail.cycle.starts_on} – {detail.cycle.ends_on}</span></>}</header>{!detail.cycle ? <div className="cycle-open"><p className="hint">Nothing scheduled into this cycle yet.</p></div> : detail.issues.length === 0 ? <div className="cycle-open"><p className="hint">Nothing scheduled into {detail.cycle.name} yet.</p></div> : groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev">⌄</span><StatusIcon value={status} /><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={() => {}} onOpen={() => {}} />)}</ul></section>)}</div> }
  return <ul>{cycles.map(cycle => { const percent = cycle.total_issues ? Math.round(cycle.done_issues * 100 / cycle.total_issues) : 0; const isOpen = cycle.state === 'current' && chart; return <li key={cycle.id}><div className={`cycle-row is-${cycle.state}`}><span className="icon"><Icon name="cycles" size={14} /></span>{cycle.state === 'current' || cycle.state === 'upcoming' ? <button className="title link-button" onClick={() => open(cycle.state)}>{cycle.name}</button> : <span className="title">{cycle.name}</span>}<span className="muted cycle-dates">{new Date(`${cycle.starts_on}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: '2-digit' })} – {new Date(`${cycle.ends_on}T00:00:00`).toLocaleDateString(undefined, { month: 'short', day: '2-digit' })}</span><span className={`cycle-state ${cycle.state}`}>{cycle.state === 'current' ? 'Current' : cycle.state === 'upcoming' ? 'Upcoming' : 'Past'}</span><span className="progress-mini" role="img" aria-label={`${cycle.done_issues} of ${cycle.total_issues} issues done`}><span style={{ width: `${percent}%` }} /></span><span className="muted progress-count">{cycle.total_issues ? `${cycle.done_issues}/${cycle.total_issues}` : '0 scope'}</span></div>{isOpen && <CycleBurnupChart chart={chart} cycleName={cycle.name} />}</li> })}</ul>
}

function Cycles({ team, view = 'all' }) {
  const [cycles, setCycles] = useState([]); const [chart, setChart] = useState(null); const [detail, setDetail] = useState(null)
  useEffect(() => { api(`/api/teams/${team.key}/cycles`).then(data => { setCycles(data.cycles); setChart(data.chart) }) }, [team])
  async function open(state) { setDetail(await api(`/api/teams/${team.key}/cycles/${state}`)) }
  useEffect(() => { if (view === 'current' || view === 'upcoming') open(view) }, [view, team])
  if (detail) { const total = detail.issues.length; const done = detail.issues.filter(issue => issue.status === 'done').length; const groups = Object.keys(STATUS_LABELS).map(status => [status, detail.issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length); return !detail.cycle ? <div className="empty-state"><span className="title">No {detail.state} cycle</span><span>{team.name} has no cycle in that state right now.</span><button className="btn btn-secondary" onClick={() => setDetail(null)} style={{ marginTop: 8 }}>All cycles</button></div> : total === 0 ? <div className="empty-state"><span className="title">{detail.cycle.name} is empty</span><span>Open an issue in {team.name} and pick this cycle on it.</span><button className="btn btn-primary" onClick={() => setDetail(null)} style={{ marginTop: 8 }}>Team issues</button></div> : <><div className="cycle-open" style={{ borderBottom: '1px solid var(--border)' }}><div className="row between"><p className="hint">{done} of {total} done · {Math.floor(done * 100 / total)}%</p><span className="progress-mini" style={{ width: 160 }} role="img" aria-label={`${done} of ${total} issues done`}><span style={{ width: `${done * 100 / total}%` }} /></span></div></div>{groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev"><Icon name="chevron" size={11} /></span><StatusIcon value={status} /><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={() => {}} onOpen={() => {}} />)}</ul></section>)}</> }
  return <div className="cycles-page"><div className="cycles-tabs" role="tablist"><button className={`cycles-tab ${view === 'all' ? 'active' : ''}`} onClick={() => setDetail(null)}>All cycles</button><button className={`cycles-tab ${view === 'current' ? 'active' : ''}`} onClick={() => open('current')}>Current</button><button className={`cycles-tab ${view === 'upcoming' ? 'active' : ''}`} onClick={() => open('upcoming')}>Upcoming</button></div><ul>{cycles.map(cycle => { const percent = cycle.total_issues ? Math.round(cycle.done_issues * 100 / cycle.total_issues) : 0; return <li key={cycle.id}><div className={`cycle-row is-${cycle.state}`}><span className="icon"><Icon name="cycles" size={14} /></span>{cycle.state === 'current' || cycle.state === 'upcoming' ? <button className="title link-button" onClick={() => open(cycle.state)}>{cycle.name}</button> : <span className="title">{cycle.name}</span>}<span className="muted cycle-dates">{cycle.starts_on} – {cycle.ends_on}</span><span className={`cycle-state ${cycle.state}`}>{cycle.state === 'current' ? 'Current' : cycle.state === 'upcoming' ? 'Upcoming' : 'Past'}</span><span className="progress-mini" role="img" aria-label={`${cycle.done_issues} of ${cycle.total_issues} issues done`}><span style={{ width: `${percent}%` }} /></span><span className="muted progress-count">{cycle.total_issues ? `${cycle.done_issues}/${cycle.total_issues}` : '0 scope'}</span></div>{cycle.state === 'current' && chart && <CycleBurnupChart chart={chart} cycleName={cycle.name} />}</li> })}</ul></div>
}

function Settings({ session, onSaved }) {
  const querySection = new URLSearchParams(window.location.search).get('settings')
  const [section, setSection] = useState(querySection || 'profile'); const [form, setForm] = useState({ first_name: session.user.name || '', last_name: '', email: session.user.email || '' }); const [saved, setSaved] = useState(false)
  async function submit(event) { event.preventDefault(); const user = await api('/api/settings/profile', { method: 'PATCH', body: JSON.stringify(form) }); setSaved(true); onSaved(user) }
  const nav = [['Personal', [['Preferences', null], ['Profile', 'profile'], ['Notifications', null], ['Code & reviews', null], ['Security & access', 'security'], ['Connected accounts', 'accounts'], ['Agent personalization', null]]], ['Administration', [['Workspace', 'workspace'], ['Teams', 'teams'], ['Members', 'members'], ['Security', 'workspace-security'], ['API', 'api'], ['Integrations', 'integrations'], ['Applications', null], ['Billing', null], ['Import & export', null]]]]
  const pageTitles = { profile: 'Profile', security: 'Security & access', accounts: 'Connected accounts', api: 'API', integrations: 'Integrations', workspace: 'Workspace', teams: 'Teams', members: 'Members', 'workspace-security': 'Security' }
  function go(next) { if (next) setSection(next) }
  return <div className="app"><nav className="sidebar settings-sidebar" aria-label="Settings"><button className="settings-back" onClick={() => window.location.href = '/'}><Icon name="chevron" size={13} /> Back to app</button>{nav.map(([heading, items]) => <div key={heading}><div className="sidebar-section">{heading}</div>{items.map(([label, target]) => target ? <button key={label} className={`nav-item ${section === target ? 'active' : ''}`} onClick={() => go(target)}><span className="label">{label}</span></button> : <span key={label} className="nav-item pending" aria-disabled="true"><span className="label">{label}</span></span>)}</div>)}</nav><main className="app-main"><div className="app-body"><div className="settings-page"><header><h1>{pageTitles[section] || 'Settings'}</h1><p>{section === 'profile' ? `How you appear to everyone in ${session.workspace?.name || 'your workspace'}.` : section === 'security' ? 'Your password and the sessions signed in as you.' : section === 'accounts' ? 'The ways this account can sign in.' : ''}</p></header>{section === 'profile' && <form onSubmit={submit}><div className="settings-block"><div className="row" style={{ gap: 16, marginBottom: 20 }}><span className="avatar xl">{(session.user.name || 'U').slice(0, 2).toUpperCase()}</span><div className="stack"><span style={{ fontWeight: 500 }}>{session.user.name}</span><span className="hint">{session.user.email || 'No email on file'}</span></div></div></div><div className="settings-block"><h2>Name</h2><div className="row" style={{ gap: 12, marginTop: 12 }}><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="first_name">First name</label><input className="input" id="first_name" value={form.first_name} onChange={event => setForm({ ...form, first_name: event.target.value })} required /></div><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="last_name">Last name</label><input className="input" id="last_name" value={form.last_name} onChange={event => setForm({ ...form, last_name: event.target.value })} /></div></div></div><div className="settings-block"><h2>Account</h2><div className="field" style={{ marginTop: 12 }}><label>Username</label><input className="input" value={session.user.username} readOnly /><p className="hint" style={{ marginTop: 6 }}>This is what you sign in with.</p></div><div className="field" style={{ marginBottom: 0 }}><label htmlFor="email">Email</label><input className="input" id="email" type="email" value={form.email} onChange={event => setForm({ ...form, email: event.target.value })} /><p className="hint" style={{ marginTop: 6 }}>Invites to other workspaces are matched against this address.</p></div></div><div className="form-actions"><span className="hint">{saved ? 'Profile updated' : ''}</span><button className="btn btn-primary">Save changes</button></div></form>}{section === 'security' && <SecuritySettings />}{section === 'accounts' && <Accounts />}{section === 'api' && <ApiKeys />}{section === 'integrations' && <Integrations />}{section === 'workspace' && <WorkspaceSettings />}{section === 'teams' && <AdminTeams />}{section === 'members' && <AdminMembers />}{section === 'workspace-security' && <SecuritySettings />}</div></div></main></div>
}

function Accounts() {
  const [accounts, setAccounts] = useState(null)
  useEffect(() => { api('/api/settings/accounts').then(setAccounts) }, [])
  async function disconnect() { if (!window.confirm('Disconnect Google from this account?')) return; await api('/api/settings/accounts/google', { method: 'DELETE' }); setAccounts({ ...accounts, google_connected: false }) }
  if (!accounts) return <div className="loading">Loading…</div>
  return <div><div className="settings-block"><div className="row between"><div className="row" style={{ gap: 12 }}><span className="avatar lg" style={{ background: '#4285f4' }}>G</span><div className="stack"><span style={{ fontWeight: 500 }}>Google</span><span className="hint">{accounts.google_connected ? `Connected${accounts.email ? ` · ${accounts.email}` : ''}` : accounts.google_enabled ? 'Not connected' : 'Not configured on this server'}</span></div></div>{accounts.google_connected ? <button className="btn btn-danger" disabled={!accounts.has_password} onClick={disconnect}>Disconnect</button> : accounts.google_enabled ? <a className="btn btn-secondary" href={`${API}/auth/google/link`}>Connect</a> : <span className="hint">Unavailable</span>}</div>{accounts.google_connected && !accounts.has_password && <p className="hint" style={{ marginTop: 12 }}>Google is currently your only way in, so it cannot be disconnected. Set a password first from Security &amp; access.</p>}</div><div className="settings-block"><div className="row between"><div className="row" style={{ gap: 12 }}><span className="avatar lg">{accounts.username.slice(0, 2).toUpperCase()}</span><div className="stack"><span style={{ fontWeight: 500 }}>Password</span><span className="hint">{accounts.has_password ? 'Set' : 'Not set'} · signs in as {accounts.username}</span></div></div><button className="btn btn-secondary" onClick={() => window.history.pushState({}, '', '?settings=security')}>{accounts.has_password ? 'Change' : 'Set a password'}</button></div></div></div>
}

function Integrations() {
  const [items, setItems] = useState([]); const [target, setTarget] = useState({})
  async function load() { const data = await api('/api/settings/integrations'); setItems(data.integrations) }
  useEffect(() => { load() }, [])
  async function connect(item) { const value = target[item.slug] || window.prompt(`${item.target_label || 'Target'}:`, item.target || ''); if (!value) return; await api(`/api/settings/integrations/${item.slug}`, { method: 'POST', body: JSON.stringify({ target: value }) }); load() }
  async function toggle(item) { await api(`/api/settings/integrations/${item.slug}`, { method: 'PATCH' }); load() }
  async function disconnect(item) { if (!window.confirm(`Disconnect ${item.name}?`)) return; await api(`/api/settings/integrations/${item.slug}`, { method: 'DELETE' }); load() }
  return <div className="settings-page integration-grid">{items.map(item => <article className={`integration-card ${item.connected ? 'is-connected' : ''}`} key={item.slug}><div className="integration-head"><span className="integration-logo" style={{ '--logo': item.color, '--logo-text': item.text || '#fff' }}>{item.letter}</span><span className="stack"><b>{item.name}</b><small>{item.connected ? item.enabled ? 'Connected' : 'Paused' : 'Not connected'}</small></span></div><p className="integration-summary">{item.summary}</p>{item.target && <code>{item.target}</code>}<div className="integration-actions">{item.connected && <><button className="btn btn-secondary" onClick={() => toggle(item)}>{item.enabled ? 'Pause' : 'Resume'}</button><button className="btn btn-danger" onClick={() => disconnect(item)}>Disconnect</button></>}{item.slug !== 'github' && <button className={`btn ${item.connected ? 'btn-ghost' : 'btn-primary'}`} onClick={() => connect(item)}>{item.connected ? 'Edit' : 'Connect'}</button>}{item.slug === 'github' && <a className="btn btn-primary" href={`${API}/settings/integrations/github/install`}>Install GitHub App</a>}</div></article>)}</div>
}

function SecuritySettings() {
  const [settings, setSettings] = useState(null); const [saved, setSaved] = useState(false); const [error, setError] = useState(''); const [password, setPassword] = useState({ current_password: '', new_password: '', confirm_password: '' }); const [passwordMessage, setPasswordMessage] = useState('')
  useEffect(() => { api('/api/settings/security').then(setSettings) }, [])
  async function submit(event) { event.preventDefault(); setError(''); try { const data = await api('/api/settings/security', { method: 'PATCH', body: JSON.stringify(settings) }); setSettings(data); setSaved(true) } catch (err) { setError(err.message) } }
  async function savePassword(event) { event.preventDefault(); setPasswordMessage(''); try { const data = await api('/api/settings/security/password', { method: 'POST', body: JSON.stringify(password) }); setPasswordMessage(data.message); setPassword({ current_password: '', new_password: '', confirm_password: '' }) } catch (err) { setPasswordMessage(err.message) } }
  async function clearSessions() { const data = await api('/api/settings/security/sessions', { method: 'POST' }); setPasswordMessage(data.message) }
  if (!settings) return <div className="loading">Loading…</div>
  return <div>{error && <div className="banner error">{error}</div>}<div className="settings-block"><h2>{settings.has_password ? 'Change password' : 'Set a password'}</h2>{!settings.has_password && <p className="hint" style={{ marginTop: 4 }}>You signed up with Google, so this account has no password yet. Setting one gives you a second way in — and is what lets you disconnect Google later.</p>}<form onSubmit={savePassword} style={{ marginTop: 16 }}>{settings.has_password && <div className="field"><label htmlFor="current-password">Current password</label><input className="input" id="current-password" type="password" value={password.current_password} onChange={event => setPassword({ ...password, current_password: event.target.value })} required /></div>}<div className="field"><label htmlFor="new-password">New password</label><input className="input" id="new-password" type="password" value={password.new_password} onChange={event => setPassword({ ...password, new_password: event.target.value })} required minLength={8} /><p className="hint" style={{ marginTop: 6 }}>At least 8 characters.</p></div><div className="field" style={{ marginBottom: 0 }}><label htmlFor="confirm-password">Confirm new password</label><input className="input" id="confirm-password" type="password" value={password.confirm_password} onChange={event => setPassword({ ...password, confirm_password: event.target.value })} required /></div><div className="form-actions"><span className="hint">{passwordMessage}</span><button className="btn btn-primary">{settings.has_password ? 'Change password' : 'Set password'}</button></div></form></div><div className="settings-block"><h2>Sessions</h2><p className="hint" style={{ marginTop: 4 }}>Signs out every other browser and device where you are logged in, and leaves this one alone.</p><button className="btn btn-secondary" style={{ marginTop: 16 }} onClick={clearSessions}>Log out of all other sessions</button></div><div className="settings-block"><h2>Signed in with</h2><div className="row between" style={{ marginTop: 12 }}><span className="hint">This session is authenticated with your current sign-in method.</span><button className="btn btn-ghost" onClick={() => window.history.pushState({}, '', '?settings=accounts')}>Connected accounts</button></div></div></div>
}

function ApiKeys() {
  const [keys, setKeys] = useState([]); const [label, setLabel] = useState(''); const [fresh, setFresh] = useState('')
  async function load() { const data = await api('/api/settings/api-keys'); setKeys(data.keys) }
  useEffect(() => { load() }, [])
  async function create(event) { event.preventDefault(); const data = await api('/api/settings/api-keys', { method: 'POST', body: JSON.stringify({ label }) }); setFresh(data.key); setLabel(''); load() }
  async function revoke(id) { if (!window.confirm('Revoke this key?')) return; await api(`/api/settings/api-keys/${id}`, { method: 'DELETE' }); load() }
  return <div>{fresh && <div className="settings-block key-reveal"><h2>Copy this key now</h2><p className="hint" style={{ marginTop: 4 }}>It is not stored — this is the one and only time it can be shown. If you lose it, revoke the key and make another.</p><input className="input copyable" value={fresh} readOnly onFocus={event => event.target.select()} style={{ marginTop: 12 }} /><p className="hint" style={{ marginTop: 12 }}>Use it as a bearer token:</p><pre className="code-block">{`curl -H "Authorization: Bearer ${fresh}" ${window.location.origin}/`}</pre></div>}<div className="settings-block"><h2>Create a key</h2><form onSubmit={create} style={{ marginTop: 12 }}><div className="row" style={{ gap: 12, alignItems: 'flex-end' }}><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="key-label">What is it for?</label><input className="input" id="key-label" placeholder="CI bot" value={label} onChange={event => setLabel(event.target.value)} required /></div><button className="btn btn-primary">Create key</button></div></form></div>{keys.length ? <div className="settings-block" style={{ padding: 0 }}><table className="settings-table"><thead><tr><th>Key</th><th>Created</th><th>Last used</th><th /></tr></thead><tbody>{keys.map(key => <tr key={key.id}><td><span className="stack"><span>{key.label}</span><span className="hint"><code>{key.prefix}…</code></span></span></td><td className="muted">{key.created_at ? new Date(key.created_at).toLocaleDateString() : '—'}</td><td className="muted">{key.last_used_at ? new Date(key.last_used_at).toLocaleDateString() : 'Never'}</td><td style={{ textAlign: 'right' }}><button className="btn btn-danger" onClick={() => revoke(key.id)}>Revoke</button></td></tr>)}</tbody></table></div> : <p className="hint">No keys yet.</p>}<div className="settings-block"><h2>What a key can do</h2><p className="hint" style={{ marginTop: 4 }}>A key authenticates as you, on every page this app serves. Revoking the key is the way to stop it.</p></div></div>
}

function AdminTeams() {
  const [teams, setTeams] = useState([]); const [name, setName] = useState(''); const [key, setKey] = useState(''); const [color, setColor] = useState('#5e6ad2')
  async function load() { const data = await api('/api/settings/teams'); setTeams(data.teams) }
  useEffect(() => { load() }, [])
  async function create(event) { event.preventDefault(); await api('/api/settings/teams', { method: 'POST', body: JSON.stringify({ name, key: key || null, color }) }); setName(''); setKey(''); load() }
  const palette = ['#5e6ad2', '#26b5ce', '#f2994a', '#eb5757', '#27ae60', '#9b51e0']
  return <div><div className="settings-block" style={{ padding: 0 }}><table className="settings-table"><thead><tr><th>Team</th><th>Key</th><th>Members</th><th>Issues</th><th /></tr></thead><tbody>{teams.map(team => <tr key={team.id}><td><span className="row" style={{ gap: 8 }}><span className="avatar" style={{ background: team.color || '#5e6ad2' }}>{team.key.slice(0, 2)}</span>{team.name}</span></td><td><code>{team.key}</code></td><td className="muted">{team.members}</td><td className="muted">{team.issues}</td><td style={{ textAlign: 'right' }}><button className="btn btn-ghost">Manage</button></td></tr>)}</tbody></table></div><div className="settings-block"><h2>Create a team</h2><form onSubmit={create} style={{ marginTop: 12 }}><div className="row" style={{ gap: 12, alignItems: 'flex-end' }}><div className="field" style={{ flex: 2, marginBottom: 0 }}><label htmlFor="team-name">Name</label><input className="input" id="team-name" value={name} onChange={event => setName(event.target.value)} placeholder="Engineering" required /></div><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="team-key">Key</label><input className="input" id="team-key" value={key} onChange={event => setKey(event.target.value)} placeholder="ENG" maxLength={6} /></div></div><div className="field" style={{ marginTop: 16 }}><label>Colour</label><div className="swatches">{palette.map(option => <label className="swatch" style={{ background: option }} title={option} key={option}><input type="radio" name="team-color" checked={color === option} onChange={() => setColor(option)} /></label>)}</div></div><p className="hint">Leave the key empty and it is taken from the name. It is upper-cased, cut to six characters, and made unique within this workspace.</p><div className="form-actions"><button className="btn btn-primary">Create team</button></div></form></div></div>
}

function AdminMembers() {
  const [data, setData] = useState({ members: [], invites: [] }); const [email, setEmail] = useState(''); const [role, setRole] = useState('member'); const [error, setError] = useState('')
  async function load() { setData(await api('/api/settings/members')) }
  useEffect(() => { load() }, [])
  async function invite(event) { event.preventDefault(); setError(''); try { await api('/api/settings/members/invite', { method: 'POST', body: JSON.stringify({ email, role }) }); setEmail(''); load() } catch (err) { setError(err.message) } }
  async function changeRole(member, next) { await api(`/api/settings/members/${member.id}`, { method: 'PATCH', body: JSON.stringify({ role: next }) }); load() }
  async function remove(member) { if (!window.confirm(`Remove ${member.name}?`)) return; await api(`/api/settings/members/${member.id}`, { method: 'DELETE' }); load() }
  async function revoke(invite) { await api(`/api/settings/invites/${invite.id}`, { method: 'DELETE' }); load() }
  return <div>{error && <div className="banner error">{error}</div>}<div className="settings-block" style={{ padding: 0 }}><table className="settings-table"><thead><tr><th>Member</th><th>Role</th><th /></tr></thead><tbody>{data.members.map(member => <tr key={member.id}><td><span className="row" style={{ gap: 8 }}><span className="avatar">{(member.name || member.username).slice(0, 2).toUpperCase()}</span><span className="stack"><span>{member.name}{member.is_current ? ' (you)' : ''}</span><span className="hint">{member.email || member.username}</span></span></span></td><td>{member.is_current ? <span className="muted" style={{ textTransform: 'capitalize' }}>{member.role}</span> : <select className="select" style={{ width: 120 }} value={member.role} onChange={event => changeRole(member, event.target.value)}><option value="owner">Owner</option><option value="admin">Admin</option><option value="member">Member</option></select>}</td><td style={{ textAlign: 'right' }}>{!member.is_current && <button className="btn btn-danger" onClick={() => remove(member)}>Remove</button>}</td></tr>)}</tbody></table></div><div className="settings-block"><h2>Invite someone</h2><p className="hint" style={{ marginTop: 4 }}>There is no mail server configured here, so no email is sent — the link below is yours to pass on. It expires in two weeks.</p><form onSubmit={invite} style={{ marginTop: 16 }}><div className="row" style={{ gap: 12, alignItems: 'flex-end' }}><div className="field" style={{ flex: 2, marginBottom: 0 }}><label htmlFor="member-email">Email</label><input className="input" id="member-email" type="email" value={email} onChange={event => setEmail(event.target.value)} placeholder="teammate@example.com" required /></div><div className="field" style={{ flex: 1, marginBottom: 0 }}><label>Role</label><select className="select" value={role} onChange={event => setRole(event.target.value)}><option value="member">Member</option><option value="admin">Admin</option></select></div><button className="btn btn-primary">Create invite</button></div></form></div>{data.invites.length > 0 && <div className="settings-block" style={{ padding: 0 }}><table className="settings-table"><thead><tr><th>Pending invite</th><th>Role</th><th>Link</th><th /></tr></thead><tbody>{data.invites.map(invite => <tr key={invite.id}><td>{invite.email}</td><td className="muted" style={{ textTransform: 'capitalize' }}>{invite.role}</td><td><input className="input copyable" readOnly value={`${window.location.origin}/invite/${invite.token}`} onFocus={event => event.target.select()} /></td><td style={{ textAlign: 'right' }}><button className="btn btn-ghost" onClick={() => revoke(invite)}>Revoke</button></td></tr>)}</tbody></table></div>}</div>
}

function WorkspaceSettings() {
  const [workspace, setWorkspace] = useState(null); const [saved, setSaved] = useState(false)
  useEffect(() => { api('/api/settings/workspace').then(setWorkspace) }, [])
  async function submit(event) { event.preventDefault(); const data = await api('/api/settings/workspace', { method: 'PATCH', body: JSON.stringify({ name: workspace.name, slug: workspace.slug }) }); setWorkspace(data); setSaved(true) }
  if (!workspace) return <div className="loading">Loading…</div>
  return <div><form onSubmit={submit}><div className="settings-block"><div className="field"><label htmlFor="workspace-name">Workspace name</label><input className="input" id="workspace-name" value={workspace.name} onChange={event => setWorkspace({ ...workspace, name: event.target.value })} required /></div><div className="field" style={{ marginBottom: 0 }}><label htmlFor="workspace-slug">Workspace URL</label><div className="field-row"><span className="prefix">/</span><input className="input" id="workspace-slug" value={workspace.slug} onChange={event => setWorkspace({ ...workspace, slug: event.target.value })} required /></div><p className="hint" style={{ marginTop: 6 }}>Identifies the workspace in the switcher. Lower case, letters, numbers and dashes.</p></div></div><div className="form-actions"><span className="hint">{saved ? 'Workspace updated' : ''}</span><button className="btn btn-primary">Save changes</button></div></form><div className="settings-block danger-zone"><h2>Delete this workspace</h2><p className="hint" style={{ marginTop: 4 }}>Removes every team, issue, member and pending invite in <strong>{workspace.name}</strong>. There is no undo.</p><div style={{ marginTop: 16 }}><div className="field"><label>Type <strong>{workspace.name}</strong> to confirm</label><input className="input" disabled /></div><button className="btn btn-danger" disabled>Delete workspace</button></div></div></div>
}

function MyIssues({ onOpen }) {
  const [issues, setIssues] = useState([])
  useEffect(() => { api('/api/my-issues').then(data => setIssues(data.issues)) }, [])
  const groups = Object.keys(STATUS_LABELS).map(status => [status, issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length)
  return groups.length ? <>{groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev"><Icon name="chevron" size={11} /></span><StatusIcon value={status} /><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={() => {}} onOpen={onOpen} />)}</ul></section>)}</> : <div className="empty-state"><span className="title">Nothing assigned to you</span><span>Issues assigned to you in any team show up here.</span></div>
}

function SummaryTrend({ trend, rows }) {
  if (!trend) return null
  return <figure className="chart-card"><figcaption className="row between"><div><h2>Created vs completed</h2><p className="hint">Last 14 days.</p></div><div className="legend">{trend.series.map(series => <span className="legend-item" key={series.role}><span className={`key key-${series.role}`} />{series.name} <b>{series.total}</b></span>)}</div></figcaption><svg className="trend" viewBox={`0 0 ${trend.box.width} ${trend.box.height}`} role="img" preserveAspectRatio="xMidYMid meet" aria-label="Issues created and completed each day over the last 14 days.">{trend.gridlines.map(line => <g key={line.value}><line className="grid" x1={trend.box.left} y1={line.y} x2={trend.box.right} y2={line.y} vectorEffect="non-scaling-stroke" /><text className="tick" x={trend.box.left - 10} y={line.y + 4} textAnchor="end">{line.value}</text></g>)}{trend.series.map(series => <polyline className={`trend-line line-${series.role}`} points={series.points} vectorEffect="non-scaling-stroke" key={series.role} />)}{trend.series.map(series => <g key={`${series.role}-end`}><circle className={`trend-dot dot-${series.role}`} cx={series.end[0]} cy={series.end[1]} r="4" />{trend.label_ends && <text className="end-label" x={series.end[0] - 10} y={series.end[1] - 9} textAnchor="end">{series.end_value}</text>}</g>)}{trend.dates.map(day => <text className="tick" x={day.x} y={trend.box.height - 6} textAnchor="middle" key={`${day.x}-${day.text}`}>{day.text}</text>)}</svg><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Day</th><th>Created</th><th>Completed</th></tr></thead><tbody>{(rows || []).map(row => <tr key={row.date}><td>{row.date}</td><td>{row.created}</td><td>{row.completed}</td></tr>)}</tbody></table></details></figure>
}

function LegacyTeamHome({ team, onOpenIssue, onNavigate = next => window.dispatchEvent(new CustomEvent('todo:navigate', { detail: next })) }) {
  const [data, setData] = useState(null)
  useEffect(() => { api(`/api/teams/${team.key}/home`).then(setData) }, [team])
  if (!data) return <div className="loading">Loading…</div>
  const summary = data.summary || {}; const total = summary.total ?? data.total ?? 0; const statusRows = summary.status_rows || []; const priorityRows = summary.priority_rows || []; const projects = summary.projects || []
  const statusLabel = row => STATUS_LABELS[row.key] || row.key
  return <div className="summary"><header className="team-overview"><div className="overview-main"><h1>{team.name}</h1>{team.description ? <p className="overview-description">{team.description}</p> : <p className="overview-description muted">No description yet.</p>}</div><aside className="overview-rail"><h2>Members</h2><div className="rail-avatars">{data.members?.length ? data.members.map(person => <span className="avatar" key={person.id}>{(person.name || person.username).slice(0, 2).toUpperCase()}</span>) : <span className="hint">Nobody yet</span>}</div><h2>Go to</h2><button className="rail-link" onClick={() => onNavigate('issues')}>▣ Issues</button><button className="rail-link" onClick={() => onNavigate('cycles')}>◷ Cycles</button><button className="rail-link" onClick={() => onNavigate('projects')}>◇ Projects</button></aside></header>{total === 0 ? <div className="empty-state"><span className="title">Nothing to summarise yet</span><span>Create an issue and this page starts keeping score.</span><button className="btn btn-primary" onClick={onOpenIssue} style={{ marginTop: 8 }}>＋ New issue</button></div> : <><section className="kpi-row" aria-label="Headline numbers">{(summary.tiles || []).map(tile => <div className="stat-tile" key={tile.label}><span className="stat-label">{tile.label}</span><span className="stat-value">{tile.value}</span><span className="stat-delta"><span className="muted">{tile.note}</span></span></div>)}</section><div className="chart-grid"><figure className="chart-card"><figcaption><h2>Status</h2><p className="hint">Where the team's {total} issues currently sit.</p></figcaption><div className="bars">{statusRows.map(row => <div className="bar-row" key={row.key}><span className="bar-label"><StatusIcon value={row.key} /> {statusLabel(row)}</span><span className="bar-track">{row.count ? <span className="bar" style={{ width: `${row.width}%` }} /> : null}</span><span className="bar-value">{row.count}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Status</th><th>Issues</th><th>Share</th></tr></thead><tbody>{statusRows.map(row => <tr key={row.key}><td>{statusLabel(row)}</td><td>{row.count}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></figure><figure className="chart-card"><figcaption><h2>Priority</h2><p className="hint">P1 is the most urgent.</p></figcaption><div className="bars">{priorityRows.map(row => <div className="bar-row" key={row.key}><span className="bar-label"><PriorityIcon level={row.key} /> P{row.key}</span><span className="bar-track">{row.count ? <span className="bar" style={{ width: `${row.width}%` }} /> : null}</span><span className="bar-value">{row.count}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Priority</th><th>Issues</th><th>Share</th></tr></thead><tbody>{priorityRows.map(row => <tr key={row.key}><td>P{row.key}</td><td>{row.count}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></figure></div><SummaryTrend trend={summary.trend} rows={summary.trend_rows} /></>}</div>
}

function TeamHome({ team, onOpenIssue, onNavigate = next => window.dispatchEvent(new CustomEvent('todo:navigate', { detail: next })) }) {
  const [data, setData] = useState(null)
  useEffect(() => { api(`/api/teams/${team.key}/home`).then(setData) }, [team])
  if (!data) return <div className="loading">Loading…</div>
  const summary = data.summary || {}; const total = summary.total ?? data.total ?? 0; const projects = summary.projects || []; const workload = summary.workload || []; const recent = summary.recent || []
  const projectName = row => row.project?.name || row.name || 'Project'; const projectStatus = row => row.project?.status || row.status || 'planned'
  const projectLabel = { planned: 'Planned', in_progress: 'In progress', completed: 'Completed', canceled: 'Canceled' }
  const relative = value => value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : '—'
  return <div className="summary"><header className="team-overview"><div className="overview-main"><h1>{team.name}</h1>{team.description ? <p className="overview-description">{team.description}</p> : <p className="overview-description muted">No description yet.</p>}</div><aside className="overview-rail"><h2>Members</h2><div className="rail-avatars">{data.members?.length ? data.members.map(person => <span className="avatar" key={person.id}>{(person.name || person.username).slice(0, 2).toUpperCase()}</span>) : <span className="hint">Nobody yet</span>}</div><h2>Go to</h2><button className="rail-link" onClick={() => onNavigate('issues')}>▣ Issues</button><button className="rail-link" onClick={() => onNavigate('cycles')}>◷ Cycles</button><button className="rail-link" onClick={() => onNavigate('projects')}>◇ Projects</button></aside></header>{total === 0 ? <div className="empty-state"><span className="title">Nothing to summarise yet</span><span>Create an issue and this page starts keeping score.</span><button className="btn btn-primary" onClick={onOpenIssue} style={{ marginTop: 8 }}>＋ New issue</button></div> : <><section className="kpi-row" aria-label="Headline numbers">{(summary.tiles || []).map(tile => <div className="stat-tile" key={tile.label}><span className="stat-label">{tile.label}</span><span className="stat-value">{tile.value}</span><span className="stat-delta"><span className="muted">{tile.note}</span></span></div>)}</section><div className="chart-grid"><figure className="chart-card"><figcaption><h2>Status</h2><p className="hint">Where the team's {total} issues currently sit.</p></figcaption><div className="bars">{(summary.status_rows || []).map(row => <div className="bar-row" key={row.key}><span className="bar-label"><StatusIcon value={row.key} /> {STATUS_LABELS[row.key]}</span><span className="bar-track">{row.count ? <span className="bar" style={{ width: `${row.width}%` }} /> : null}</span><span className="bar-value">{row.count}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Status</th><th>Issues</th><th>Share</th></tr></thead><tbody>{(summary.status_rows || []).map(row => <tr key={row.key}><td>{STATUS_LABELS[row.key]}</td><td>{row.count}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></figure><figure className="chart-card"><figcaption><h2>Priority</h2><p className="hint">P1 is the most urgent.</p></figcaption><div className="bars">{(summary.priority_rows || []).map(row => <div className="bar-row" key={row.key}><span className="bar-label"><PriorityIcon level={row.key} /> P{row.key}</span><span className="bar-track">{row.count ? <span className="bar" style={{ width: `${row.width}%` }} /> : null}</span><span className="bar-value">{row.count}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Priority</th><th>Issues</th><th>Share</th></tr></thead><tbody>{(summary.priority_rows || []).map(row => <tr key={row.key}><td>P{row.key}</td><td>{row.count}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></figure></div>{projects.length > 0 && <figure className="chart-card"><figcaption className="row between"><div><h2>Projects</h2><p className="hint">How far each feature has got. A bar is the share of that project's own issues that are done.</p></div><button className="btn btn-ghost" onClick={() => onNavigate('projects')}>All projects</button></figcaption><div className="bars">{projects.map(row => <div className="bar-row" key={row.project?.id || row.id}><button className="bar-label link-button" onClick={() => onNavigate('projects')}><StatusIcon value={projectStatus(row) === 'completed' ? 'done' : projectStatus(row) === 'in_progress' ? 'in_progress' : 'todo'} /> {projectName(row)}</button><span className="bar-track">{row.percent ? <span className="bar" style={{ width: `${row.percent}%` }} /> : null}</span><span className="bar-value">{row.done}/{row.total}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Project</th><th>Status</th><th>Done</th><th>Issues</th><th>Progress</th></tr></thead><tbody>{projects.map(row => <tr key={row.project?.id || row.id}><td>{projectName(row)}</td><td>{projectLabel[projectStatus(row)] || projectStatus(row)}</td><td>{row.done}</td><td>{row.total}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></figure>}<SummaryTrend trend={summary.trend} rows={summary.trend_rows} /><div className="chart-grid"><figure className="chart-card"><figcaption><h2>Workload</h2><p className="hint">Open issues per person — finished work is not a load, so it is not counted here.</p></figcaption>{workload.length ? <><div className="bars">{workload.map(row => <div className="bar-row" key={row.person?.id || 'unassigned'}><span className="bar-label"><span className="avatar">{row.person ? (row.person.name || row.person.username).slice(0, 2).toUpperCase() : '?'}</span>{row.person?.name || row.person?.username || 'Unassigned'}</span><span className="bar-track"><span className="bar" style={{ width: `${row.width}%` }} /></span><span className="bar-value">{row.count}</span></div>)}</div><details className="table-view"><summary>Show data</summary><table className="data-table"><thead><tr><th>Person</th><th>Open issues</th><th>Share</th></tr></thead><tbody>{workload.map(row => <tr key={row.person?.id || 'unassigned'}><td>{row.person?.name || row.person?.username || 'Unassigned'}</td><td>{row.count}</td><td>{row.percent}%</td></tr>)}</tbody></table></details></> : <p className="hint" style={{ padding: '12px 0' }}>Nothing open — the team is clear.</p>}</figure><section className="chart-card"><figcaption><h2>Recent activity</h2><p className="hint">The last {recent.length} issue{recent.length !== 1 ? 's' : ''} to change.</p></figcaption><ul className="activity">{recent.map(entry => <li key={entry.issue?.id}><StatusIcon value={entry.issue?.status} /><button className="identifier link-button" onClick={() => { onOpenIssue(entry.issue); onNavigate('issues') }}>{entry.issue?.identifier}</button><button className="activity-title link-button" onClick={() => { onOpenIssue(entry.issue); onNavigate('issues') }}>{entry.issue?.title}</button><span className="hint">{relative(entry.issue?.updated_at)}</span></li>)}</ul></section></div></>}</div>
}

function LegacyProjectDetail({ project, onBack, onOpenIssue, onEdit }) {
  const done = project.issues.filter(issue => issue.status === 'done').length; const percent = project.issues.length ? Math.round(done * 100 / project.issues.length) : 0
  return <div className="issue-detail"><div><button className="btn btn-ghost" onClick={onBack}>← Back to projects</button><div className="detail-header"><div><p className="eyebrow">PROJECT</p><h1>{project.name}</h1></div><button className="btn btn-secondary" onClick={onEdit}>Edit</button></div><div className="issue-description">{project.description || <span className="muted">No description</span>}</div><h2 className="section-title">Issues <span className="muted">{project.issues.length}</span></h2>{project.issues.length ? <ul>{project.issues.map(issue => <li className="issue-row" key={issue.id}><button className="issue-title-button" onClick={() => onOpenIssue(issue)}><span className="identifier">{issue.identifier}</span> {issue.title}</button><span className="muted">{STATUS_LABELS[issue.status]}</span></li>)}</ul> : <p className="hint">Nothing under this feature yet.</p>}</div><aside className="issue-props"><div className="prop-row"><span className="prop-label">Status</span><span className="prop-value">{project.status}</span></div><div className="prop-row"><span className="prop-label">Team</span><span className="prop-value">{project.team?.name || '—'}</span></div><div className="prop-row"><span className="prop-label">Target</span><span className="prop-value hint">{project.target_date || '—'}</span></div><div className="prop-row"><span className="prop-label">Progress</span><span className="stack" style={{ flex: 1, gap: 6, padding: '4px 6px' }}><span className="progress-mini"><span style={{ width: `${percent}%` }} /></span><span className="hint">{project.issues.length ? `${done} of ${project.issues.length} done · ${percent}%` : 'No issues yet'}</span></span></div></aside></div>
}

function ProjectForm({ team, project, onClose, onSaved }) {
  const [form, setForm] = useState({ name: project?.name || '', description: project?.description || '', project_status: project?.status || 'planned', lead_id: project?.lead_id || '', target_date: project?.target_date || '' })
  async function submit(event) { event.preventDefault(); const path = project ? `/api/projects/${project.id}` : `/api/teams/${team.key}/projects`; const saved = await api(path, { method: project ? 'PATCH' : 'POST', body: JSON.stringify({ ...form, lead_id: form.lead_id ? Number(form.lead_id) : null }) }); onSaved(saved) }
  const labels = { planned: 'Planned', in_progress: 'In progress', completed: 'Completed', canceled: 'Canceled' }
  return <div className="content-narrow"><nav className="breadcrumb"><button className="breadcrumb-button" onClick={onClose}>Projects</button><Icon name="chevron" size={11} />{project ? <><button className="breadcrumb-button current" onClick={onClose}>{project.name}</button><Icon name="chevron" size={11} /><span>Edit</span></> : <span>New</span>}</nav><form onSubmit={submit}><div className="field"><label htmlFor="project-name">Name</label><input className="input" id="project-name" value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} required autoFocus placeholder="Login rework" /><p className="hint" style={{ marginTop: 6 }}>A feature: one deliverable, made of several issues.</p></div><div className="field"><label htmlFor="project-description">Description</label><textarea className="textarea" id="project-description" value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} placeholder="What this feature delivers, and why" /></div><div className="row" style={{ gap: 12, alignItems: 'flex-end' }}><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="project_status">Status</label><select className="select" id="project_status" value={form.project_status} onChange={event => setForm({ ...form, project_status: event.target.value })}>{Object.entries(labels).map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></div><div className="field" style={{ flex: 1, marginBottom: 0 }}><label htmlFor="target_date">Target date</label><input className="input" id="target_date" name="target_date" type="date" value={form.target_date || ''} onChange={event => setForm({ ...form, target_date: event.target.value })} /></div></div><div className="form-actions"><button className="btn btn-primary">{project ? 'Save' : 'Create project'}</button><button className="btn btn-ghost" type="button" onClick={onClose}>Cancel</button></div></form></div>
}

function ProjectDetail({ project, onBack, onOpenIssue, onEdit }) {
  const groups = Object.keys(STATUS_LABELS).map(status => [status, project.issues.filter(issue => issue.status === status)]).filter(([, items]) => items.length); const total = project.issues.length; const done = project.issues.filter(issue => issue.status === 'done').length; const percent = total ? Math.round(done * 100 / total) : 0
  return <div className="issue-detail"><div><h1>{project.name}</h1><div className="issue-description">{project.description || <span className="muted">No description</span>}</div><h2 className="section-title" style={{ margin: '28px 0 4px' }}>Issues <span className="muted">{total}</span></h2>{total ? <><p className="hint" style={{ marginBottom: 12 }}>The tasks this feature is made of.</p>{groups.map(([status, items]) => <section className="issue-group" key={status}><div className="issue-group-header"><button className="group-toggle" type="button"><span className="chev"><Icon name="chevron" size={11} /></span><StatusIcon value={status} /><span>{STATUS_LABELS[status]}</span><span className="count">{items.length}</span></button></div><ul>{items.map(issue => <IssueRow key={issue.id} issue={issue} onStatus={() => {}} onOpen={onOpenIssue} />)}</ul></section>)}</> : <p className="hint" style={{ marginTop: 8 }}>Nothing under this feature yet. Open an issue in {project.team?.name || 'the team'} and pick this project on it.</p>}</div><aside className="issue-props"><div className="prop-row"><span className="prop-label">Status</span><span className="prop-value">{project.status}</span></div><div className="prop-row"><span className="prop-label">Lead</span><span className="prop-value">Unassigned</span></div><div className="prop-row"><span className="prop-label">Team</span><span className="prop-value"><TeamBadge team={project.team} /> {project.team?.name || '—'}</span></div><div className="prop-row"><span className="prop-label">Target</span><span className="prop-value hint">{project.target_date ? new Date(project.target_date).toLocaleDateString(undefined, { month: 'short', day: '2-digit', year: 'numeric' }) : '—'}</span></div><div className="prop-row" style={{ alignItems: 'flex-start' }}><span className="prop-label">Progress</span><span className="stack" style={{ flex: 1, gap: 6, padding: '4px 6px' }}><span className="progress-mini" role="img" aria-label={`${done} of ${total} issues done`}><span style={{ width: `${percent}%` }} /></span><span className="hint">{total ? `${done} of ${total} done · ${percent}%` : 'No issues yet'}</span></span></div><div className="menu-separator" style={{ margin: '12px 0' }} /><button className="btn btn-ghost" onClick={onBack}>Back to projects</button></aside></div>
}

function WorkspaceShell({ session, team, page, issues, error, newIssue, selectedIssue, editingIssue, selectedProject, projectEditor, onTeam, onNavigate, onNewIssue, onLogout, onStatus, onOpenIssue, onSelectIssue, onEditIssue, onDeleteIssue, onSaveEdit, onCloseNewIssue, onCreatedIssue, onOpenProject, onCloseProject, onEditProject, onOpenProjectIssue, onSaveProject, onCloseProjectEditor }) {
  const title = page === 'home' || page === 'issues' ? team?.name : page === 'my-issues' ? 'My issues' : page === 'projects' ? 'Projects' : page === 'cycles' || page === 'cycles-current' || page === 'cycles-upcoming' ? 'Cycles' : page === 'members-admin' ? 'Members' : page === 'teams-admin' ? 'Teams' : page === 'workspace-admin' ? 'Workspace' : 'Settings'
  return <div className={`app ${newIssue ? 'is-new-issue' : ''}`}><OriginalSidebar session={session} team={team} page={page} onTeam={onTeam} onNavigate={onNavigate} onNewIssue={onNewIssue} onLogout={onLogout} /><main className="app-main"><header className="app-header"><MainHeader page={page} team={team} issues={issues} selectedIssue={selectedIssue} editingIssue={editingIssue} selectedProject={selectedProject} onBack={() => { onSelectIssue(null); onEditIssue(null) }} onEdit={() => onEditIssue(selectedIssue)} onNewIssue={onNewIssue} onNewProject={() => onOpenProject({ new: true })} pageTitle={title} /></header><div className="app-body">{error && <div className="banner error">{error}</div>}{newIssue && team && <NewIssue team={team} onClose={onCloseNewIssue} onCreated={onCreatedIssue} />}{!newIssue && team && page === 'home' && <TeamHome team={team} onOpenIssue={() => onNavigate('issues')} />}{!newIssue && team && page === 'issues' && !selectedIssue && !editingIssue && <IssueList team={team} issues={issues} onStatus={onStatus} onNewIssue={onNewIssue} onOpen={onOpenIssue} />}{!newIssue && team && page === 'issues' && selectedIssue && !editingIssue && <IssueDetail issue={selectedIssue} onBack={() => onSelectIssue(null)} onEdit={() => onEditIssue(selectedIssue)} onStatus={onStatus} onDeleted={onDeleteIssue} />}{!newIssue && team && page === 'issues' && editingIssue && <EditIssue issue={editingIssue} onBack={() => onEditIssue(null)} onSaved={onSaveEdit} />}{!newIssue && page === 'my-issues' && <MyIssues onOpen={issue => { onSelectIssue(issue); onNavigate('issues') }} />}{!newIssue && team && page === 'projects' && !selectedProject && <Projects team={team} onOpen={onOpenProject} />}{!newIssue && team && page === 'projects' && selectedProject && <ProjectDetail project={selectedProject} onBack={onCloseProject} onEdit={() => onEditProject(selectedProject)} onOpenIssue={onOpenProjectIssue} />}{!newIssue && team && (page === 'cycles' || page === 'cycles-current' || page === 'cycles-upcoming') && <Cycles team={team} view={page === 'cycles-current' ? 'current' : page === 'cycles-upcoming' ? 'upcoming' : 'all'} />}{!newIssue && page === 'teams-admin' && <AdminTeams />}{!newIssue && page === 'members-admin' && <AdminMembers />}{!newIssue && page === 'workspace-admin' && <WorkspaceSettings />}</div></main>{projectEditor && team && <ProjectForm team={team} project={projectEditor.id ? projectEditor : null} onClose={onCloseProjectEditor} onSaved={onSaveProject} />}</div>
}

function App() {
  const inviteToken = window.location.pathname.startsWith('/invite/') ? window.location.pathname.split('/')[2] : null
  const [session, setSession] = useState(null); const [team, setTeam] = useState(null); const [issues, setIssues] = useState([]); const [error, setError] = useState(''); const [newIssue, setNewIssue] = useState(false); const [page, setPage] = useState(new URLSearchParams(window.location.search).has('settings') ? 'settings' : 'issues'); const [selectedIssue, setSelectedIssue] = useState(null); const [editingIssue, setEditingIssue] = useState(null); const [selectedProject, setSelectedProject] = useState(null); const [projectEditor, setProjectEditor] = useState(null); const [authMode, setAuthMode] = useState('login')
  async function load() { try { const me = await api('/api/me'); setSession(me); const selected = team || me.teams[0]; if (selected) { setTeam(selected); const result = await api(`/api/teams/${selected.key}/issues`); setIssues(result.issues) } } catch (err) { setSession(err.status === 409 ? 'no-workspace' : false); setError(err.message) } }
  useEffect(() => { if (!inviteToken) load() }, [inviteToken])
  useEffect(() => { const navigate = event => setPage(event.detail); window.addEventListener('todo:navigate', navigate); return () => window.removeEventListener('todo:navigate', navigate) }, [])
  if (inviteToken) return <InvitePage token={inviteToken} />
  if (session === null) return <div className="loading">Loading…</div>
  if (session === 'no-workspace') return <CreateWorkspace onCreated={() => { setSession(null); load() }} />
  if (session === false) return authMode === 'register' ? <Register onLogin={() => { setAuthMode('login'); setSession(null); load() }} onBack={() => setAuthMode('login')} /> : <Login onLogin={() => { setSession(null); load() }} onRegister={() => setAuthMode('register')} />
  async function selectTeam(next) { setTeam(next); const result = await api(`/api/teams/${next.key}/issues`); setIssues(result.issues) }
  async function changeStatus(issue, status) { const updated = await api(`/api/issues/${issue.identifier}`, { method: 'PATCH', body: JSON.stringify({ issue_status: status }) }); setIssues(items => items.map(item => item.id === updated.id ? updated : item)); return updated }
  if (page === 'settings') return <Settings session={session} onSaved={user => setSession({ ...session, user })} />
  const title = editingIssue ? `Edit ${editingIssue.identifier}` : selectedIssue ? selectedIssue.identifier : selectedProject ? selectedProject.name : page === 'issues' || page === 'home' ? team?.name : page === 'my-issues' ? 'My issues' : page === 'projects' ? 'Projects' : page === 'cycles' ? 'Cycles' : page === 'members-admin' ? 'Members' : page === 'teams-admin' ? 'Teams' : page === 'workspace-admin' ? 'Workspace' : 'Settings'
  const pageHeading = page === 'issues' && team ? <><TeamBadge team={team} size={15} /><span>{team.name}</span>{!selectedIssue && !editingIssue && <span className="muted">{issues.length}</span>}</> : page === 'projects' ? <><Icon name="projects" size={15} /><span>Projects</span></> : page === 'cycles' ? <><Icon name="cycles" size={15} /><span>Cycles</span></> : <span>{title || 'Workspace'}</span>
  return <WorkspaceShell session={session} team={team} page={page} issues={issues} error={error} newIssue={newIssue} selectedIssue={selectedIssue} editingIssue={editingIssue} selectedProject={selectedProject} projectEditor={projectEditor} onTeam={selectTeam} onNavigate={next => { setSelectedIssue(null); setEditingIssue(null); setSelectedProject(null); setPage(next) }} onNewIssue={() => setNewIssue(true)} onLogout={() => { setSession(false); setTeam(null); setIssues([]); setPage('issues') }} onStatus={async (issue, status) => { const updated = await changeStatus(issue, status); if (selectedIssue) setSelectedIssue(updated) }} onOpenIssue={setSelectedIssue} onSelectIssue={setSelectedIssue} onEditIssue={setEditingIssue} onDeleteIssue={() => { setIssues(items => items.filter(item => item.id !== selectedIssue.id)); setSelectedIssue(null) }} onSaveEdit={updated => { setIssues(items => items.map(item => item.id === updated.id ? updated : item)); setSelectedIssue(updated); setEditingIssue(null) }} onCloseNewIssue={() => setNewIssue(false)} onCreatedIssue={issue => { setIssues(items => [...items, issue]); setNewIssue(false) }} onOpenProject={async project => { if (project.new) { setProjectEditor({}); return } setSelectedProject(await api(`/api/projects/${project.id}`)) }} onCloseProject={() => setSelectedProject(null)} onEditProject={setProjectEditor} onOpenProjectIssue={issue => { setSelectedProject(null); setSelectedIssue(issue); setPage('issues') }} onSaveProject={async saved => { setProjectEditor(null); setSelectedProject(await api(`/api/projects/${saved.id}`)) }} onCloseProjectEditor={() => setProjectEditor(null)} />
  return <div className="app"><OriginalSidebar session={session} team={team} page={page} onTeam={selectTeam} onNavigate={next => { setSelectedIssue(null); setEditingIssue(null); setSelectedProject(null); setPage(next) }} onNewIssue={() => setNewIssue(true)} onLogout={() => { setSession(false); setTeam(null); setIssues([]); setPage('issues') }} /><main className="app-main"><header className="app-header"><span className="page-title"><span className="team-mark">●</span><span>{title || 'Workspace'}</span>{page === 'issues' && !selectedIssue && !editingIssue && <span className="muted">{issues.length}</span>}</span><span className="spacer" />{page === 'issues' && !selectedIssue && !editingIssue && <button className="btn btn-secondary" onClick={() => setNewIssue(true)}>＋ New issue</button>}{page === 'projects' && !selectedProject && <button className="btn btn-secondary" onClick={() => setProjectEditor({})}>＋ New project</button>}</header><div className="app-body">{error && <div className="banner error">{error}</div>}{team && page === 'home' && <TeamHome team={team} onOpenIssue={() => setPage('issues')} />}{team && page === 'issues' && !selectedIssue && !editingIssue && <IssueList team={team} issues={issues} onStatus={changeStatus} onNewIssue={() => setNewIssue(true)} onOpen={setSelectedIssue} />}{team && page === 'issues' && selectedIssue && !editingIssue && <IssueDetail issue={selectedIssue} onBack={() => setSelectedIssue(null)} onEdit={() => setEditingIssue(selectedIssue)} onStatus={async (issue, status) => { const updated = await changeStatus(issue, status); setSelectedIssue(updated) }} onDeleted={() => { setIssues(items => items.filter(item => item.id !== selectedIssue.id)); setSelectedIssue(null) }} />}{team && page === 'issues' && editingIssue && <EditIssue issue={editingIssue} onBack={() => setEditingIssue(null)} onSaved={updated => { setIssues(items => items.map(item => item.id === updated.id ? updated : item)); setSelectedIssue(updated); setEditingIssue(null) }} />}{page === 'my-issues' && <MyIssues onOpen={issue => { setSelectedIssue(issue); setPage('issues') }} />}{team && page === 'projects' && !selectedProject && <Projects team={team} onOpen={async project => { const detail = await api(`/api/projects/${project.id}`); setSelectedProject(detail) }} />}{team && page === 'projects' && selectedProject && <ProjectDetail project={selectedProject} onBack={() => setSelectedProject(null)} onEdit={() => setProjectEditor(selectedProject)} onOpenIssue={issue => { setSelectedProject(null); setSelectedIssue(issue); setPage('issues') }} />}{team && page === 'cycles' && <Cycles team={team} />}{page === 'settings' && <Settings session={session} onSaved={user => setSession({ ...session, user })} />}{page === 'teams-admin' && <AdminTeams />}{page === 'members-admin' && <AdminMembers />}{page === 'workspace-admin' && <WorkspaceSettings />}</div></main>{newIssue && team && <NewIssue team={team} onClose={() => setNewIssue(false)} onCreated={issue => { setIssues(items => [...items, issue]); setNewIssue(false) }} />}{projectEditor && team && <ProjectForm team={team} project={projectEditor.id ? projectEditor : null} onClose={() => setProjectEditor(null)} onSaved={async saved => { setProjectEditor(null); const detail = await api(`/api/projects/${saved.id}`); setSelectedProject(detail) }} />}</div>
}

createRoot(document.getElementById('root')).render(<App />)
